var PATH_BOOK_GEO = {"subject": "地理", "book": "必修第一册", "version": "人教版", "chapters": [{"no": "第一章", "title": "宇宙中的地球", "units": ["u_geo_1", "u_geo_2", "u_geo_3", "u_geo_4", "u_geo_5"]}, {"no": "第二章", "title": "地球上的大气", "units": ["u_geo_6", "u_geo_7", "u_geo_8"]}], "order": ["u_geo_1", "u_geo_2", "u_geo_3", "u_geo_4", "u_geo_5", "u_geo_6", "u_geo_7", "u_geo_8"], "nodes": {"geo_g001": {"name": "天体与天体系统", "sec": 1, "secTitle": "地球的宇宙环境", "page": 2, "desc": "天体判断两条标准；天体系统四层次；八大行星顺序与小行星带位置。", "criteria": ["能复述本节核心概念与数据", "能看懂案例图表的判读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清判读依据"], "diag": null, "pre": [], "next": ["geo_g002"], "content": {"advance": {"a": "流星体是天体；流星是流星体进入大气层摩擦发光的现象，不是天体本身；陨石已落到地面、不再在宇宙空间运行，不是天体。", "kind": "self", "q": "判断：流星体、流星、陨石，哪些是天体？并说明判断标准。"}, "apply": [{"ans": 1, "opts": ["银河系→太阳系→地月系→地球", "可观测宇宙→银河系→太阳系→地月系", "太阳系→银河系→可观测宇宙→地月系", "地月系→太阳系→可观测宇宙→银河系"], "q": "天体系统层次由高到低排序正确的是（ ）", "why": "层次：可观测宇宙（总星系）＞银河系＞太阳系＞地月系。"}, {"ans": 2, "opts": ["金星与地球之间", "地球与火星之间", "火星与木星之间", "木星与土星之间"], "q": "小行星带位于（ ）", "why": "小行星带位于火星与木星轨道之间。"}], "basics": [{"ans": 0, "opts": ["恒星", "行星", "卫星", "星云"], "q": "自身能发光发热的天体是（ ）", "why": "恒星由炽热气体组成，自身能发光发热；行星、卫星靠反射恒星光。"}, {"ans": 1, "opts": ["水星、金星、地球、火星、木星、土星、天王星、海王星", "金星、水星、火星、地球、土星、木星、海王星、天王星", "水星、地球、金星、火星、木星、土星、天王星、海王星", "水星、金星、火星、地球、木星、土星、天王星、海王星"], "q": "八大行星距太阳由近及远的顺序是（ ）", "why": "水金地火、木土、天海，口诀即可锁定。"}], "case": {"a": "哈雷彗星是天体（在太阳系中运行的物质）；拖着尾巴是它接近太阳时物质受热挥发形成的彗尾，属于该天体的组成部分/现象，不改变其天体身份。", "hints": ["天体判断两条标准：①在宇宙空间中运行；②是物质实体。", "现象（如光芒、尾巴的表现）不是独立物质实体。"], "q": "材料：每隔约 76 年，哈雷彗星会拖着长长的尾巴回归内太阳系。哈雷彗星是不是天体？它的「尾巴」是不是天体？说出判断依据。", "steps": ["哈雷彗星是太阳系内按轨道运行的物质实体，满足天体两条标准，是天体。", "彗尾是彗星接近太阳时，冰物质升华并受太阳风吹拂形成的现象，随彗星本体存在。", "结论：彗星是天体；彗尾是彗星的组成部分与现象，不是独立天体。"], "talk": ["天体辨认题只问两句：它在宇宙里运行吗？它是实物吗？两条都满足就是天体。"], "title": "案例：哈雷彗星算不算天体"}, "intro": "宇宙里的一切物质都是**天体**，但并不是所有「光」都是天体。==判断一个东西是不是天体，看两条：是否位于宇宙空间、是否独立运行的物质实体。==这一节先解决「有什么、在哪一层」的问题。", "learn": [{"h": "天体的主要类型", "p": "**恒星**（自身发光发热）、**行星**（绕恒星运行、质量足够大）、**卫星**（绕行星运行）、**星云**（气体尘埃云）、**彗星**（拖尾、周期回归）、**流星体**（小颗粒）。太阳是离地球最近的恒星，月球是地球唯一的天然卫星。"}, {"h": "天体系统的四个层次", "p": "天体互相吸引、绕转形成天体系统，由低到高：**地月系→太阳系→银河系→可观测宇宙（总星系）**。\n\n==层次题最易错的是银河系与太阳系的从属：太阳系只是银河系中普通一员。==地球在每一层中的定位都要能脱口而出。"}, {"h": "八大行星的排布规律", "p": "由近及远：**水金地火**（类地行星）、**木土**（巨行星）、**天王星、海王星**（远日行星）。行星公转具有**同向性、共面性、近圆性**——这为地球提供了安全的运行环境（下一节点用）。火星与木星之间是**小行星带**。"}], "pitfalls": ["把流星、极光等现象当作天体。", "天体系统层次顺序记反（尤其银河系与太阳系）。"], "svg": "<rect x='120' y='8' width='140' height='28' rx='6' fill='#2563eb'/><text x='190' y='27' text-anchor='middle' font-size='12' fill='#fff'>可观测宇宙</text><rect x='120' y='50' width='140' height='28' rx='6' fill='#60a5fa'/><text x='190' y='69' text-anchor='middle' font-size='12'>银河系</text><rect x='120' y='92' width='140' height='28' rx='6' fill='#93c5fd'/><text x='190' y='111' text-anchor='middle' font-size='12'>太阳系</text><rect x='120' y='134' width='140' height='28' rx='6' fill='#dbeafe'/><text x='190' y='153' text-anchor='middle' font-size='12'>地月系（地球）</text>", "svgCap": "天体系统层次：地球同时属于四个层次，答题要答全。"}, "video": {"bvid": "BV1VCxQedEVW", "p": 4, "t": "1-1【辞典】地球的宇宙环境", "dur": "38:34", "from": "一地er", "vtop": ["天体判断两条：位置在宇宙空间、本身是物质实体。", "层次顺序：地月系→太阳系→银河系→可观测宇宙。", "生命条件五条：光稳、道安、温度、大气、液态水。"], "vsum": "第一节解决定位问题：天体（恒星、行星、卫星、星云、彗星、流星体）与现象（流星、极光）要分清；**天体系统**四层次（地月系、太阳系、银河系、可观测宇宙）要背序；八大行星水金地火、木土、天海，**小行星带**在火星与木星之间。地球的特殊性用五条条件框架表达——外部：太阳光照稳定、行星各行其道；自身：**日地距离适中**（温度适宜）、体积质量适中（大气适宜）、有液态水。==这五条是本章所有大题的答题目录==。视频为一地er《高中地理必修一基础与考点大合集》1-1【辞典】地球的宇宙环境（38:34）。\n易错提醒：流星、极光是自然现象而不是天体，判断天体时千万别把它们算进去。", "vtech": ["看到「是不是天体」→ 只问两句：在宇宙空间吗？是实物吗？", "看到宜居性分析题 → 拿出五条清单逐条对：有/无+证据，不许凭感觉。", "看到行星排序/分类 → 先写口诀（水金地火木土天海）再落笔选项。"], "vgaokao": []}}, "geo_g002": {"name": "地球的普通性与特殊性：存在生命的条件", "sec": 2, "secTitle": "地球的宇宙环境", "page": 4, "desc": "生命条件五条清单：外部（光稳、道安）+自身（温度、大气、液态水），全章答题模板。", "criteria": ["能复述本节核心概念与数据", "能看懂案例图表的判读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清判读依据"], "diag": null, "pre": ["geo_g001"], "next": ["geo_g003", "geo_g009"], "content": {"advance": {"a": "不能只凭一条下结论：还要看恒星的光照是否稳定、行星轨道是否安全、火星自身温度与大气、水等条件。综合看：火星缺少适宜温度、液态水（地表）和可呼吸大气，直接移居不成立（问题研究课会展开）。", "kind": "self", "q": "有人说「火星和地球同在太阳系宜居带附近，所以火星一定有生命」。用本节框架指出这个推理缺了哪些环节。"}, "apply": [{"ans": 2, "opts": ["太阳光照稳定", "行星各行其道", "体积质量适中形成大气", "日地距离适中"], "q": "金星表面温度高达 460 ℃以上、无液态水，最主要的原因对应地球生命条件的哪一条不满足（ ）", "why": "金星距太阳太近，温度过高——对应「日地距离适中」这一温度条件不满足。"}, {"ans": 1, "opts": ["自身条件—温度", "外部条件—安全的宇宙环境", "自身条件—大气", "外部条件—稳定的光照"], "q": "月球昼夜温差达 300 ℃以上，直接原因是没有大气保温，这对应地球的（ ）", "why": "月球质量小、无大气，保温与削弱作用缺失，属自身条件中的大气条件。"}], "basics": [{"ans": 0, "opts": ["日地距离适中，有适宜温度", "太阳光照稳定", "行星互不干扰", "体积质量适中"], "q": "地球上有液态水存在的温度前提是（ ）", "why": "日地距离适中使地表平均温度约 15 ℃，水能以液态存在。"}, {"ans": 1, "opts": ["外部条件：太阳系大小行星各行其道、运行环境安全", "自身条件：地球体积质量适中", "外部条件：太阳光照稳定", "自身条件：原始海洋形成"], "q": "「大小行星各行其道、互不干扰」属于地球存在生命的（ ）", "why": "这是外部（宇宙环境）条件，与太阳光照稳定并列。"}], "case": {"a": "没有。二氧化碳大气极稀薄、表面气压极低，又缺少全球性磁场保护；更关键的是平均温度过低且昼夜温差大、表面无稳定液态水，大气条件与温度条件都不达标。", "hints": ["套框架：外部条件（光照、轨道安全）逐条对，再对自身条件（温度、大气、水）。", "二氧化碳「有大气」不等于「大气合适」——厚度与成分都要看。"], "q": "材料：火星有以二氧化碳为主的大气，但大气层非常稀薄，表面平均温度约 −63 ℃，地表没有稳定的液态水。火星具备地球那样的生命存在条件吗？用「外部/自身」框架逐条分析。", "steps": ["外部条件：太阳光照相对稳定、火星轨道环境基本安全——大致具备。", "自身—温度：平均 −63 ℃，远低于液态水稳定存在的范围，不具备。", "自身—大气：稀薄且以 CO₂ 为主，无游离氧、保温差，不具备。", "自身—水：地表无稳定液态水（仅两极有冰），不具备。结论：不具备类似地球的生命条件。"], "talk": ["条件分析题用清单法：把地球的四五条条件当答题目录，逐条「有/无+证据」，这是地理大题的标准骨架。"], "title": "案例：用地球条件清单审火星"}, "intro": "太阳系八大行星，只有地球有生命。==分析地球存在生命的条件有一套固定框架：外部条件看太阳和行星际空间，自身条件看温度、大气和水。==这套框架是本章最重要的答题模板，后面审火星、审任何系外行星都用它。", "learn": [{"h": "外部条件（宇宙环境给的）", "p": "**稳定的太阳光照**：太阳处于壮年期，光照长期稳定，生命演化不被打断。**安全的行星际空间**：大小行星各行其道、互不干扰，地球运行轨道安全。这两条是「位置好」。"}, {"h": "自身条件（地球自己的）", "p": "**温度适宜**：日地距离适中（约 1.5 亿千米），地表平均温度约 15 ℃，水能保持液态。**大气适宜**：体积、质量适中，引力恰好能吸附大气，形成厚度成分适宜的大气层（保温+供氧）。**液态水**：地球内部水汽释放并冷却凝结，形成原始海洋。\n\n==答条件题的万能结构：外部两条（光稳、道安）+自身三条（温、气、水），共五条，缺一不可。=="}, {"h": "易错提醒", "p": "易错提醒：「地球自转周期适中」不是教材五条件之一，别往里塞；金星的问题是距日太近（温度）、火星的问题是质量太小（大气稀薄）+温度低，一星一因要配准。"}], "pitfalls": ["条件分类错位（把日地距离适中归到外部条件）。", "只背结论，不会用证据（温度数值、大气厚度）支撑判断。"], "svg": "<rect x='15' y='25' width='160' height='30' rx='6' fill='#e0f2fe'/><text x='95' y='45' text-anchor='middle' font-size='12'>外部：光照稳定</text><rect x='15' y='65' width='160' height='30' rx='6' fill='#e0f2fe'/><text x='95' y='85' text-anchor='middle' font-size='12'>外部：轨道安全</text><rect x='205' y='25' width='160' height='30' rx='6' fill='#dcfce7'/><text x='285' y='45' text-anchor='middle' font-size='12'>自身：温度适宜</text><rect x='205' y='65' width='160' height='30' rx='6' fill='#dcfce7'/><text x='285' y='85' text-anchor='middle' font-size='12'>自身：大气适宜 · 有液态水</text><text x='190' y='120' text-anchor='middle' font-size='12' fill='#64748b'>五条清单 = 一切「宜居性」大题的答题目录</text>", "svgCap": "地球生命条件框架：外部 2 条 + 自身 3 条。"}, "video": {"bvid": "BV1VCxQedEVW", "p": 4, "t": "1-1【辞典】地球的宇宙环境", "dur": "38:34", "from": "一地er", "vtop": ["天体判断两条：位置在宇宙空间、本身是物质实体。", "层次顺序：地月系→太阳系→银河系→可观测宇宙。", "生命条件五条：光稳、道安、温度、大气、液态水。"], "vsum": "第一节解决定位问题：天体（恒星、行星、卫星、星云、彗星、流星体）与现象（流星、极光）要分清；**天体系统**四层次（地月系、太阳系、银河系、可观测宇宙）要背序；八大行星水金地火、木土、天海，**小行星带**在火星与木星之间。地球的特殊性用五条条件框架表达——外部：太阳光照稳定、行星各行其道；自身：**日地距离适中**（温度适宜）、体积质量适中（大气适宜）、有液态水。==这五条是本章所有大题的答题目录==。视频为一地er《高中地理必修一基础与考点大合集》1-1【辞典】地球的宇宙环境（38:34）。\n易错提醒：流星、极光是自然现象而不是天体，判断天体时千万别把它们算进去。", "vtech": ["看到「是不是天体」→ 只问两句：在宇宙空间吗？是实物吗？", "看到宜居性分析题 → 拿出五条清单逐条对：有/无+证据，不许凭感觉。", "看到行星排序/分类 → 先写口诀（水金地火木土天海）再落笔选项。"], "vgaokao": []}}, "geo_g003": {"name": "太阳辐射与地球", "sec": 3, "secTitle": "太阳对地球的影响", "page": 8, "desc": "太阳辐射的影响清单与分布规律：青藏高原最高、四川盆地最低的成因对照。", "criteria": ["能复述本节核心概念与数据", "能看懂案例图表的判读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清判读依据"], "diag": null, "pre": ["geo_g002"], "next": ["geo_g004"], "content": {"advance": {"a": "不一致。太阳辐射量看「到达地面的多少」，四川盆地阴雨多、云雾厚，太阳辐射被削弱得多，是我国太阳辐射低值中心；而纬度相近的青藏高原因海拔高、空气稀薄、水汽少，成为高值中心。纬度只是影响因素之一。", "kind": "self", "q": "「纬度越低，太阳辐射一定越强」对吗？用青藏高原与四川盆地的例子说明。"}, "apply": [{"ans": 1, "opts": ["拉萨", "成都", "上海", "哈尔滨"], "q": "下列城市中年太阳辐射总量最丰富的是（ ）", "why": "拉萨位于青藏高原，海拔高、空气稀薄、晴天多，是我国太阳辐射高值区（「日光城」）。"}, {"ans": 2, "opts": ["纬度低，正午太阳高度大", "地势高，空气稀薄", "降水少，晴天多", "距海远，水汽少"], "q": "青藏高原太阳辐射强的原因，不包括（ ）", "why": "青藏高原纬度并不低，它辐射强主要靠海拔高、空气稀薄、水汽和云量少。"}], "basics": [{"ans": 0, "opts": ["太阳内部的核聚变反应", "太阳表面的黑子活动", "太阳大气耀斑爆发", "太阳风的吹拂"], "q": "太阳辐射的能量来自（ ）", "why": "太阳辐射能量源于其内部的核聚变反应。"}, {"ans": 1, "opts": ["为地球提供光和热，维持地表温度", "直接导致火山喷发", "引起潮汐现象", "是地热能的主要来源"], "q": "太阳辐射对地球最基础的作用是（ ）", "why": "提供光热、维持地表温度，并驱动大气运动与水循环；潮汐主要源于天体引力。"}], "case": {"a": "因为植被覆盖率高、森林光合作用所固定的太阳能（生物能）总量大，即「太阳能转化为生物能」的效率体现在生产力上，与到达地面的辐射总量是两个不同的量。", "hints": ["先分清两个概念：辐射总量 vs 单位面积生产力。", "热带雨林的水热组合好、光合作用全年旺盛。"], "q": "材料：我国青藏高原是太阳辐射高值中心，但单位面积绿色植物固定的太阳能（生产力）却以热带雨林地区最高。如何解释这组看似矛盾的数据？", "steps": ["青藏高原海拔高、空气稀薄，太阳辐射总量确实高。", "但高原气温低、生长季短，植被稀疏，光合作用把辐射转成生物能的比例很低。", "热带雨林纬度低、水热充足、全年生长，固定太阳能的效率与总量都高。", "结论：辐射强不等于生物生产力高，中间隔着温度、水分与植被的转化环节。"], "talk": ["地理矛盾材料题，先拆概念：题里藏着两个不同的指标（总量/效率），拆开就不矛盾了。"], "title": "案例：辐射最强的地方，生产力不是最高"}, "intro": "太阳是地球的能量总开关。==太阳辐射为地球提供光和热，是大气运动、水循环的主要能源，我们用的煤和石油也是古代生物固定的太阳能。==本节的拿分点在分布规律：为什么青藏高原最强、四川盆地最弱。", "learn": [{"h": "太阳辐射的影响清单", "p": "提供**光热**、维持地表温度；驱动**大气运动和水循环**；为生物光合作用提供能量（生物能、化石燃料的源头）；人类直接利用（太阳能发电、热水器）。答「太阳辐射对地球的影响」就按这四条展开。"}, {"h": "分布规律与中国极值区", "p": "全球：由低纬向高纬**递减**（正午太阳高度与昼长差异）。我国高值中心：**青藏高原**（海拔高、空气稀薄、晴天多）；低值中心：**四川盆地**（地势低、云雾多、阴雨天多）。\n\n==判断某地辐射强弱，看三样：纬度（太阳高度）、海拔（空气厚度）、天气（云量水汽）。三条要一起看，只看纬度必错。=="}, {"h": "易错提醒", "p": "易错提醒：太阳辐射强不等于气温高——青藏高原辐射强但气温低（空气稀薄保温差），这是最爱考的反直觉组合。"}], "pitfalls": ["「辐射强=气温高」的直觉错误。", "四川盆地辐射弱的原因只答纬度（应答云雾多、地势低）。"], "svg": "<rect x='30' y='30' width='150' height='34' rx='6' fill='#fef3c7'/><text x='105' y='52' text-anchor='middle' font-size='12'>青藏高原：最高值</text><rect x='210' y='30' width='150' height='34' rx='6' fill='#e2e8f0'/><text x='285' y='52' text-anchor='middle' font-size='12'>四川盆地：最低值</text><text x='105' y='85' text-anchor='middle' font-size='11' fill='#64748b'>海拔高 · 空气稀薄 · 晴天多</text><text x='285' y='85' text-anchor='middle' font-size='11' fill='#64748b'>云雾多 · 阴雨多 · 地势低</text><text x='195' y='112' text-anchor='middle' font-size='12'>判断三要素：纬度 + 海拔 + 天气</text>", "svgCap": "我国太阳辐射的两个极值区及成因对照。"}, "video": {"bvid": "BV1VCxQedEVW", "p": 6, "t": "1-2【辞典】太阳对地球的影响", "dur": "29:04", "from": "一地er", "vtop": ["辐射强弱看三样：纬度、海拔、天气（云量）。", "黑子是标志（光球层），耀斑是显示（色球层）。", "太阳活动影响：通信、磁暴、极光、气候。"], "vsum": "第二节分辐射与活动两半：太阳辐射源于**核聚变**，提供光热、驱动大气与水循环、是化石燃料的能量源头；==分布由低纬向高纬递减==，我国极值是青藏高原（海拔高、空气稀薄）与四川盆地（云雾多），且辐射强不等于气温高。太阳活动按层次记：光球层**黑子**（11 年周期、活动标志）、色球层**耀斑**（最激烈显示）、日冕层**太阳风**；影响四条：扰动电离层影响短波通信、磁暴、极光（高纬）、与气候相关。视频为一地er《高中地理必修一基础与考点大合集》1-2【辞典】太阳对地球的影响（29:04）。\n易错提醒：黑子是太阳活动的标志、耀斑是太阳活动最激烈的显示，两者的说法不能互换。", "vtech": ["看到辐射强弱比较 → 三要素 checklist：纬度、海拔、云量，逐项比完再下结论。", "看到黑子/耀斑概念题 → 先定位层次，标志与显示绝不互换。", "看到统计相关材料 → 措辞只用「相关/可能影响」，不写「决定」。"], "vgaokao": []}}, "geo_g004": {"name": "太阳活动与地球", "sec": 4, "secTitle": "太阳对地球的影响", "page": 10, "desc": "黑子（标志，光球层）、耀斑（显示，色球层）、太阳风（日冕层）与四类影响。", "criteria": ["能复述本节核心概念与数据", "能看懂案例图表的判读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清判读依据"], "diag": null, "pre": ["geo_g003"], "next": [], "content": {"advance": {"a": "依据：他的现象都与地磁场受扰动有关——磁暴期间磁针指向紊乱、指南针失灵；同时太阳活动增强时高纬地区极光增多。两者同源于太阳风与高能带电粒子冲击地球磁场和大气层。", "kind": "self", "q": "极光的出现和指南针失灵常常同时发生，这说明了什么？从太阳活动的影响角度解释。"}, "apply": [{"ans": 1, "opts": ["黑子", "耀斑", "日珥", "太阳风"], "q": "太阳活动最激烈的显示、释放巨大能量的是（ ）", "why": "耀斑是色球层突然增亮增大的斑块，是太阳活动最激烈的显示。"}, {"ans": 2, "opts": ["引发火山地震", "使地球自转变慢", "扰动电离层，影响无线电短波通信", "直接升高全球气温数十度"], "q": "耀斑爆发时对地球的直接影响是（ ）", "why": "耀斑抛射的电磁辐射与粒子扰动电离层，短波通信会中断、衰减。"}], "basics": [{"ans": 0, "opts": ["光球层", "色球层", "日冕层", "日核"], "q": "黑子出现在太阳的（ ）", "why": "太阳黑子是光球层上温度较低、显得暗淡的斑点。"}, {"ans": 1, "opts": ["约11年", "约22年", "约76年", "约1年"], "q": "太阳黑子活动的周期约为（ ）", "why": "黑子数目变化周期约为 11 年，是判断太阳活动强弱的主要标志。"}], "case": {"a": "有关系。黑子是太阳活动强弱的标志，黑子多的年份太阳活动强，往往气候异常（如降水异常带移动）增多；但这是统计相关，具体机制复杂，不能简单说某次旱涝就是黑子造成的。", "hints": ["黑子是「标志」不是「原因本身」，答题时措辞要严谨。", "气候影响属于相关性证据，考试认可「可能相关」，不认可「直接决定」。"], "q": "材料：统计发现，太阳黑子多的年份，地球上某些地区的降水异常增多、农业歉收概率上升。这能证明黑子直接决定气候吗？应该怎样表述太阳活动与气候的关系？", "steps": ["确认现象：黑子数与某些气候指标存在统计上的相关性，教材也承认这种相关。", "辨明性质：黑子是太阳活动的标志，太阳活动增强时辐射与粒子环境变化，可能扰动大气环流。", "得出表述：太阳活动与气候变化存在相关性，但不是单一决定因素，答题用「可能影响」而非「决定」。"], "talk": ["地理题措辞决定对错：相关≠因果。看到统计材料，先答「存在相关」，再谨慎谈机制。"], "title": "案例：黑子多，雨就多吗"}, "intro": "太阳也有「情绪波动」：黑子、耀斑、日珥、太阳风就是太阳活动。==记太阳活动，先定位层次：光球层—黑子，色球层—耀斑和日珥，日冕层—太阳风。==再记影响的四条线：通信、磁场、极光、气候。", "learn": [{"h": "三种主要活动与层次", "p": "**黑子**（光球层）：温度低于周围的暗斑，数量变化周期约 **11 年**，是太阳活动强弱的**标志**。**耀斑**（色球层）：突然释放巨大能量，是太阳活动最激烈的**显示**。**太阳风**（日冕层）：高速带电粒子流。日珥也在色球层。\n\n标志与显示别混：黑子是标志，耀斑是显示——这是选择题的固定挖坑点。"}, {"h": "对地球的四类影响", "p": "**扰动电离层**：影响无线电**短波通信**；**扰乱磁场**：产生**磁暴**，指南针不能正确指示方向；**极光**：高能粒子轰击高层大气，在两极高纬地区形成极光；**气候与灾害**：与降水异常、地震水旱等存在统计相关性。\n\n==影响记忆口诀：通信断、磁针乱、极光现、气候连。=="}, {"h": "易错提醒", "p": "易错提醒：极光只出现在**高纬度**（两极附近）夜空，低纬地区看不到；太阳活动影响的是短波通信，不是所有通信方式（光纤、长波不受这一机制影响）。"}], "pitfalls": ["黑子（标志）与耀斑（显示）的概念互换。", "极光出现纬度答成全球/中纬度。"], "svg": "<circle cx='90' cy='70' r='38' fill='#fbbf24'/><circle cx='78' cy='60' r='7' fill='#92400e'/><circle cx='102' cy='82' r='5' fill='#92400e'/><text x='90' y='125' text-anchor='middle' font-size='12'>光球层：黑子（标志）</text><rect x='190' y='25' width='170' height='28' rx='6' fill='#fee2e2'/><text x='275' y='44' text-anchor='middle' font-size='12'>色球层：耀斑（最激烈显示）</text><rect x='190' y='62' width='170' height='28' rx='6' fill='#e0f2fe'/><text x='275' y='81' text-anchor='middle' font-size='12'>日冕层：太阳风</text><rect x='190' y='99' width='170' height='28' rx='6' fill='#dcfce7'/><text x='275' y='118' text-anchor='middle' font-size='12'>影响：通信 / 磁暴 / 极光 / 气候</text>", "svgCap": "太阳活动：层次—类型—影响三段对应。"}, "video": {"bvid": "BV1VCxQedEVW", "p": 6, "t": "1-2【辞典】太阳对地球的影响", "dur": "29:04", "from": "一地er", "vtop": ["辐射强弱看三样：纬度、海拔、天气（云量）。", "黑子是标志（光球层），耀斑是显示（色球层）。", "太阳活动影响：通信、磁暴、极光、气候。"], "vsum": "第二节分辐射与活动两半：太阳辐射源于**核聚变**，提供光热、驱动大气与水循环、是化石燃料的能量源头；==分布由低纬向高纬递减==，我国极值是青藏高原（海拔高、空气稀薄）与四川盆地（云雾多），且辐射强不等于气温高。太阳活动按层次记：光球层**黑子**（11 年周期、活动标志）、色球层**耀斑**（最激烈显示）、日冕层**太阳风**；影响四条：扰动电离层影响短波通信、磁暴、极光（高纬）、与气候相关。视频为一地er《高中地理必修一基础与考点大合集》1-2【辞典】太阳对地球的影响（29:04）。\n易错提醒：黑子是太阳活动的标志、耀斑是太阳活动最激烈的显示，两者的说法不能互换。", "vtech": ["看到辐射强弱比较 → 三要素 checklist：纬度、海拔、云量，逐项比完再下结论。", "看到黑子/耀斑概念题 → 先定位层次，标志与显示绝不互换。", "看到统计相关材料 → 措辞只用「相关/可能影响」，不写「决定」。"], "vgaokao": []}}, "geo_g005": {"name": "地层、化石与地质年代表", "sec": 5, "secTitle": "地球的历史", "page": 14, "desc": "地层即时间：下老上新；化石断代又读环境；前寒武纪占九成时间。", "criteria": ["能复述本节核心概念与数据", "能看懂案例图表的判读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清判读依据"], "diag": null, "pre": [], "next": ["geo_g006"], "content": {"advance": {"a": "因为地层（尤其沉积岩层）形成于不同年代、含有不同化石，新老关系可以排序；化石生物的演化顺序不可逆（简单→复杂），可作为跨地区对比地层年代的「时间标签」。", "kind": "self", "q": "为什么科学家能用地层和化石「读」出地球的历史？从地层形成顺序和生物演化顺序两个角度回答。"}, "apply": [{"ans": 1, "opts": ["岩浆岩地层", "沉积岩地层", "变质岩地层", "玄武岩地层"], "q": "研究地球历史最主要的地层是（ ）", "why": "沉积岩地层层理与化石保存最好，是重建地球历史的主要依据。"}, {"ans": 2, "opts": ["距今时间越久", "地层形成越晚", "沉积环境越深", "化石越复杂"], "q": "一般情况下，下层地层比上层地层（ ）", "why": "沉积顺序先下后上，下层形成更早（除非地层被构造运动翻转）。"}], "basics": [{"ans": 0, "opts": ["化石", "矿物晶体", "岩浆", "断层"], "q": "保存在地层中、用于判断地层年代与古环境的是（ ）", "why": "化石是古代生物的遗体或遗迹，是地层断代与环境重建的关键证据。"}, {"ans": 1, "opts": ["46亿年", "4.6亿年", "460亿年", "1亿年"], "q": "地球的年龄约为（ ）", "why": "地球形成于约 46 亿年前。"}], "case": {"a": "该地层形成于海洋环境（有三叶虫等海生无脊椎动物），当时气候温暖、海平面较高，属古生代早期的海洋沉积。", "hints": ["三叶虫是古生代海洋的代表性无脊椎动物。", "由「有什么生物」推「什么环境」，再推「什么时代」。"], "q": "材料：某地灰岩层中发现大量三叶虫化石和珊瑚化石。推断该地层形成时的环境与大致时代，并说明推理链条。", "steps": ["三叶虫、珊瑚都是海洋生物，灰岩多为海洋（尤其浅海）沉积→形成环境是海洋。", "三叶虫繁盛于古生代，尤其早古生代海洋。", "珊瑚礁指示温暖浅海。综合：该地层形成于古生代温暖的浅海环境。"], "talk": ["化石推理链：生物种类→生活环境→沉积环境→地质时代，按这条链一步步写，阅卷按点给分。"], "title": "案例：从化石读环境"}, "intro": "地球 46 亿年的历史写在地层里。==地层像一本按时间装订的书：正常情况下下层老、上层新；化石是书里的插图，既能断代，也能还原当时的环境。==这一节是下一节「演化历程」的时间工具。", "learn": [{"h": "地层：地球的书页", "p": "**沉积岩地层**具有层理结构：先沉积的在下、后沉积的在上，因此地层顺序就是时间顺序（局部地区可能被构造运动扰动）。裸露的地层剖面可以直接「读」出一段历史。"}, {"h": "化石：断代与环境的双重证据", "p": "**化石**是保存在地层中的古代生物遗体、遗迹。同一时代的地层含相同或相近的化石；生物演化不可逆（从简单到复杂），化石组合就是地层的「时间标签」。同时，生物的生活环境写在化石里：珊瑚→温暖浅海，煤炭（蕨类）→温暖湿润的沼泽森林。"}, {"h": "地质年代表", "p": "科学家按地层顺序与同位素测年编出**地质年代表**：宙—代—纪三级（如显生宙含古生代、中生代、新生代）。**前寒武纪**占地球历史约 90% 的时间，却因化石稀少而划分粗略。\n\n易错提醒：地层顺序判读的前提是没有发生地层倒转；遇到断层、褶皱明显的剖面图，要先判断构造再断代。"}], "pitfalls": ["忽略地层倒转的前提，机械套用「下老上新」。", "把前寒武纪当成「很短的早期」（实际占 90% 时间）。"], "svg": "<rect x='110' y='12' width='170' height='26' rx='4' fill='#fef3c7'/><text x='195' y='30' text-anchor='middle' font-size='12'>新生代地层（新）</text><rect x='110' y='44' width='170' height='26' rx='4' fill='#fde68a'/><text x='195' y='62' text-anchor='middle' font-size='12'>中生代地层</text><rect x='110' y='76' width='170' height='26' rx='4' fill='#f59e0b'/><text x='195' y='94' text-anchor='middle' font-size='12'>古生代地层</text><rect x='110' y='108' width='170' height='26' rx='4' fill='#b45309'/><text x='195' y='126' text-anchor='middle' font-size='12' fill='#fff'>前寒武纪（最老·最长）</text>", "svgCap": "地层即时间：越往下越古老，前寒武纪占地球历史约九成。"}, "video": {"bvid": "BV1VCxQedEVW", "p": 8, "t": "1-3【辞典】地球的历史", "dur": "36:15", "from": "一地er", "vtop": ["地层下老上新，化石是时间标签兼环境说明书。", "四幕剧：蓝藻放氧→生物登陆→恐龙称霸→人类出现。", "两次大灭绝（古生代末、中生代末）是时代分界。"], "vsum": "第三节是时间之书：沉积地层下老上新，==化石既断代又能推环境==（珊瑚→温暖浅海、三叶虫→古生代海洋）；**地质年代表**把 46 亿年分成**前寒武纪**（占约九成，蓝藻放氧改大气）与**显生宙**三代——古生代（海洋繁盛→生物登陆、蕨类成煤）、中生代（爬行动物与恐龙、裸子植物、联合古陆解体）、新生代（哺乳动物、被子植物、人类与冰期）。两次大灭绝卡住代与代的边界。视频为一地er《高中地理必修一基础与考点大合集》1-3【辞典】地球的历史（36:15）。\n易错提醒：前寒武纪占了地球历史的约九成，千万别把它当成一段很短的早期阶段。", "vtech": ["看到化石题 → 走推理链：生物→环境→时代，一步一个得分点。", "看到演化排序 → 用四幕剧主角定位：蓝藻、三叶虫、恐龙、人类各归其幕。", "看到地层剖面图 → 先查有无倒转/断层，再用下老上新。"], "vgaokao": []}}, "geo_g006": {"name": "地球的演化历程", "sec": 6, "secTitle": "地球的历史", "page": 16, "desc": "四幕剧：前寒武纪蓝藻放氧、古生代生物登陆、中生代恐龙、新生代人类。", "criteria": ["能复述本节核心概念与数据", "能看懂案例图表的判读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清判读依据"], "diag": null, "pre": ["geo_g005"], "next": [], "content": {"advance": {"a": "中生代。因为恐龙繁盛于中生代（爬行动物时代），该时期气候温暖、裸子植物繁盛，能支撑大型爬行动物的食物网；古生代以海洋生物和两栖类为主，不可能有恐龙。", "kind": "self", "q": "某同学在煤层上方的地层里发现恐龙化石。他判断该地层属于古生代，对吗？为什么？"}, "apply": [{"ans": 1, "opts": ["前寒武纪", "古生代晚期", "中生代", "新生代"], "q": "大规模成煤时期之一、蕨类植物繁盛的是（ ）", "why": "古生代晚期蕨类繁盛，形成大量煤炭；中生代也有成煤（裸子植物）。"}, {"ans": 2, "opts": ["蓝藻出现并进行光合作用", "恐龙灭绝", "联合古陆最终解体完成", "人类出现"], "q": "前寒武纪最重要的生物事件是（ ）", "why": "蓝藻光合作用释放氧气，深刻改变了大气成分，是演化史的转折点。"}], "basics": [{"ans": 0, "opts": ["古生代", "中生代", "新生代", "前寒武纪（显生宙之前）"], "q": "恐龙繁盛、被称为「爬行动物时代」的是（ ）", "why": "中生代是爬行动物（尤其恐龙）的时代。"}, {"ans": 1, "opts": ["中生代末期", "古生代早期", "新生代中期", "前寒武纪末期"], "q": "恐龙灭绝发生在（ ）", "why": "约 6600 万年前中生代末期，恐龙等大量物种灭绝。"}], "case": {"a": "先划分：前寒武纪（生命起源与早期演化）→古生代（海洋→登陆）→中生代（爬行）→新生代（哺乳与人类）。三叶虫定位在古生代海洋阶段，恐龙在中生代陆地阶段，人类在新生代最后阶段。", "hints": ["每个时代配一个关键词：前寒武纪—蓝藻，古生代—登陆，中生代—恐龙，新生代—人类。", "灭绝事件是时代分界线：中生代结束于恐龙灭绝。"], "q": "把下列事件排进地质年代表并说出排序依据：三叶虫繁盛、恐龙称霸、人类出现、蓝藻释放氧气。", "steps": ["蓝藻释放氧气→前寒武纪（最早，改变大气成分）。", "三叶虫繁盛→古生代（海洋无脊椎动物时代）。", "恐龙称霸→中生代（爬行动物时代）。", "人类出现→新生代（最晚，哺乳动物时代之后）。排序依据：生物演化的不可逆顺序与地层化石证据。"], "talk": ["演化史记「四幕剧」：每幕记主角+一件大事，比背年表数字有效得多。"], "title": "案例：四幕演化剧排序"}, "intro": "把 46 亿年压缩成四幕剧就好记了。==前寒武纪是漫长的序幕（占九成时间），古生代生物登陆，中生代恐龙称霸，新生代哺乳动物与人类登场。==每幕记一个主角和一件大事，时间轴就立住了。", "learn": [{"h": "前寒武纪：序幕（约46亿—5.4亿年前）", "p": "地球形成初期经历熔融、分异，形成地核地幔地壳的雏形与原始海洋、大气。生命起源于海洋，**蓝藻**通过光合作用释放氧气，大气成分被改造；这一时期也是铁、金等重要矿产的形成期。真核生物、多细胞生物在末期出现。"}, {"h": "古生代与中生代：登陆与称霸", "p": "**古生代**（5.4亿—2.5亿年前）：早古生代海洋无脊椎动物空前繁盛（三叶虫、珊瑚）；晚古生代脊椎动物登陆、两栖类出现，**蕨类植物**繁盛形成大片森林与煤层；末期发生最大规模物种灭绝。**中生代**（2.5亿—6600万年前）：板块运动剧烈（联合古陆解体），**爬行动物**称霸（恐龙），裸子植物繁盛，末期恐龙等物种灭绝。\n\n==两次大灭绝是时代分界线：古生代末、中生代末，各记一个。=="}, {"h": "新生代：哺乳与人类", "p": "**新生代**（6600万年前至今）：被子植物与**哺乳动物**大发展，板块运动形成现代海陆格局与高大山系（如喜马拉雅山）；第四纪出现**人类**，并经历多次冰期—间冰期交替。人类历史在地质尺度上只是最后一瞬。"}], "pitfalls": ["把恐龙放进古生代或新生代。", "成煤期只记一个（古生代蕨类、中生代裸子植物都有重要成煤期）。"], "svg": "<rect x='8' y='45' width='86' height='40' rx='6' fill='#e0f2fe'/><text x='51' y='62' text-anchor='middle' font-size='11'>前寒武纪</text><text x='51' y='78' text-anchor='middle' font-size='11'>蓝藻放氧</text><rect x='104' y='45' width='86' height='40' rx='6' fill='#bae6fd'/><text x='147' y='62' text-anchor='middle' font-size='11'>古生代</text><text x='147' y='78' text-anchor='middle' font-size='11'>生物登陆</text><rect x='200' y='45' width='86' height='40' rx='6' fill='#7dd3fc'/><text x='243' y='62' text-anchor='middle' font-size='11'>中生代</text><text x='243' y='78' text-anchor='middle' font-size='11'>恐龙称霸</text><rect x='296' y='45' width='86' height='40' rx='6' fill='#38bdf8'/><text x='339' y='62' text-anchor='middle' font-size='11'>新生代</text><text x='339' y='78' text-anchor='middle' font-size='11'>人类出现</text><text x='195' y='25' text-anchor='middle' font-size='12'>地球历史四幕剧（左老右新）</text>", "svgCap": "演化时间轴：每幕一个主角事件。"}, "video": {"bvid": "BV1VCxQedEVW", "p": 8, "t": "1-3【辞典】地球的历史", "dur": "36:15", "from": "一地er", "vtop": ["地层下老上新，化石是时间标签兼环境说明书。", "四幕剧：蓝藻放氧→生物登陆→恐龙称霸→人类出现。", "两次大灭绝（古生代末、中生代末）是时代分界。"], "vsum": "第三节是时间之书：沉积地层下老上新，==化石既断代又能推环境==（珊瑚→温暖浅海、三叶虫→古生代海洋）；**地质年代表**把 46 亿年分成**前寒武纪**（占约九成，蓝藻放氧改大气）与**显生宙**三代——古生代（海洋繁盛→生物登陆、蕨类成煤）、中生代（爬行动物与恐龙、裸子植物、联合古陆解体）、新生代（哺乳动物、被子植物、人类与冰期）。两次大灭绝卡住代与代的边界。视频为一地er《高中地理必修一基础与考点大合集》1-3【辞典】地球的历史（36:15）。\n易错提醒：前寒武纪占了地球历史的约九成，千万别把它当成一段很短的早期阶段。", "vtech": ["看到化石题 → 走推理链：生物→环境→时代，一步一个得分点。", "看到演化排序 → 用四幕剧主角定位：蓝藻、三叶虫、恐龙、人类各归其幕。", "看到地层剖面图 → 先查有无倒转/断层，再用下老上新。"], "vgaokao": []}}, "geo_g007": {"name": "地震波与地球内部圈层", "sec": 7, "secTitle": "地球的圈层结构", "page": 21, "desc": "纵横波差异、莫霍面与古登堡面、地壳地幔地核与岩石圈的范围。", "criteria": ["能复述本节核心概念与数据", "能看懂案例图表的判读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清判读依据"], "diag": null, "pre": [], "next": ["geo_g008"], "content": {"advance": {"a": "古登堡面以下横波消失，说明外核不是固体（横波不能在液体中传播）；纵波速度骤降也符合液态特征。配合密度与温度推断：外核为液态（铁镍等），内核在高压下呈固态。", "kind": "self", "q": "科学家凭什么判断外核是液态的？只用地震波证据回答。"}, "apply": [{"ans": 1, "opts": ["莫霍面", "古登堡面", "软流层", "岩石圈底部"], "q": "横波在此界面完全消失、纵波速度骤降的是（ ）", "why": "古登堡面（约 2900 千米深处）以下横波消失、纵波减速，是地幔与地核的分界。"}, {"ans": 2, "opts": ["地壳", "地幔", "地核", "岩石圈"], "q": "一般认为岩浆的主要发源地软流层位于（ ）", "why": "软流层位于上地幔上部，岩石部分熔融，被认为是岩浆的发源地。"}], "basics": [{"ans": 0, "opts": ["纵波能在固体、液体、气体中传播，横波只能在固体中传播", "横波速度比纵波快", "纵波只能在固体中传播", "两种波的传播介质相同"], "q": "纵波与横波传播特点的正确表述是（ ）", "why": "纵波（P波）速度快、可穿三态；横波（S波）速度慢、只能穿固体。"}, {"ans": 1, "opts": ["地壳", "软流层", "地幔", "地核"], "q": "地壳与地幔的分界面是（ ）", "why": "莫霍面是地壳与地幔的分界（大陆平均深度约 33 千米处速度明显增加）。"}], "case": {"a": "划分为地壳、地幔、地核三层：莫霍面（约 33 千米）分隔壳与幔，古登堡面（约 2900 千米）分隔幔与核。依据是地震波速度在两个深度发生突变（不连续面）。", "hints": ["横波消失是液态证据，出现在哪一面？", "速度「增加」与「骤降消失」分别对应哪个界面？"], "q": "材料：地震波向下传播时，在地下约 33 千米处速度明显加快；在约 2900 千米处纵波速度骤降、横波完全消失。据此把地球内部划分为哪三层？两个界面的名称是什么？", "steps": ["波速突变处就是物质性质的分界面（不连续面）：33 千米处为莫霍面，2900 千米处为古登堡面。", "莫霍面以上为地壳，两面之间为地幔，古登堡面以下为地核。", "2900 千米以下横波消失，推断外核为液态（横波不能穿过液体）。"], "talk": ["圈层题=读图题：横轴深度、纵轴波速，找「突变点」就是界面，找「消失」就是液态证据。"], "title": "案例：读地震波速图分圈层"}, "intro": "钻井最深不过十几千米，人类了解地球内部全靠**地震波**这把「透视镜」。==纵波快、能穿三态；横波慢、只能穿固体——波速在哪里突变，哪里就是圈层的分界面。==这一节是典型的读图题地盘。", "learn": [{"h": "两条波、两个界面", "p": "**莫霍面**（地壳/地幔界，陆地平均约 33 千米）：纵、横波速度都明显**增加**。**古登堡面**（地幔/地核界，约 2900 千米）：纵波速度**骤降**、横波**消失**。由横波消失可推断：外核是**液态**。"}, {"h": "三层结构速记", "p": "**地壳**：薄而不均（大陆厚、大洋薄），由岩石组成，分硅铝层与硅镁层。**地幔**：分上、下地幔；上地幔顶部存在**软流层**（岩浆发源地）。**地核**：温度高、压强大、密度大，外核液态、内核固态，主要成分铁、镍。\n\n==岩石圈不等于地壳：岩石圈 = 地壳 + 上地幔顶部（软流层以上），是刚性外壳。=="}, {"h": "易错提醒", "p": "易错提醒：大陆地壳厚（平均约 40 千米，青藏高原可达 70 千米）、大洋地壳薄（约 5—10 千米），记「陆厚洋薄」最稳；莫霍面深度随地点变化，不是全球统一的数字。"}], "pitfalls": ["岩石圈与地壳概念混同。", "两个不连续面的深度与波速变化记反。"], "svg": "<rect x='100' y='10' width='180' height='24' rx='4' fill='#fde68a'/><text x='190' y='27' text-anchor='middle' font-size='12'>地壳（莫霍面以上）</text><rect x='100' y='40' width='180' height='44' rx='4' fill='#f59e0b'/><text x='190' y='58' text-anchor='middle' font-size='12'>地幔</text><text x='190' y='76' text-anchor='middle' font-size='11'>软流层：岩浆发源地</text><rect x='100' y='90' width='180' height='40' rx='4' fill='#dc2626'/><text x='190' y='108' text-anchor='middle' font-size='12' fill='#fff'>地核（古登堡面以下）</text><text x='190' y='124' text-anchor='middle' font-size='11' fill='#fff'>外核液态 · 内核固态</text>", "svgCap": "内部圈层：两个界面分出三层。"}, "video": {"bvid": "BV1VCxQedEVW", "p": 9, "t": "1-4【辞典】地球的圈层结构", "dur": "27:57", "from": "一地er", "vtop": ["横波只能过固体：消失处之下是液态外核。", "岩石圈 = 地壳 + 上地幔顶部，不等于地壳。", "生物圈渗透于气、水、岩三圈，没有独立一层。"], "vsum": "第四节内外两分：内部靠**地震波**——==纵波快且穿三态、横波慢且只穿固体==；**莫霍面**（壳幔界）与**古登堡面**（幔核界，约 2900 千米、横波消失→外核液态）分出地壳、地幔、地核，软流层是岩浆发源地，**岩石圈**=地壳+上地幔顶部。外部四圈：大气圈、水圈（连续不规则）、岩石圈、生物圈（渗透于其余三圈），相互联系构成人类生存环境。视频为一地er《高中地理必修一基础与考点大合集》1-4【辞典】地球的圈层结构（27:57）。\n易错提醒：岩石圈不等于地壳，它还包括上地幔的顶部，两个概念答题时不能混用。", "vtech": ["看到波速图 → 找突变点定界面，找横波消失定液态。", "看到圈层归属题 → 逐词扫描归类，再找一对作用关系最直接的。", "看到岩石圈 → 立刻默念：地壳+上地幔顶部，不是地壳本身。"], "vgaokao": []}}, "geo_g008": {"name": "地球的外部圈层", "sec": 8, "secTitle": "地球的圈层结构", "page": 24, "desc": "大气圈、水圈、岩石圈与渗透其中的生物圈：先归类，再说联系。", "criteria": ["能复述本节核心概念与数据", "能看懂案例图表的判读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清判读依据"], "diag": null, "pre": ["geo_g007"], "next": ["geo_g009"], "content": {"advance": {"a": "生物圈。因为生物圈不独立成层，而是渗透于大气圈底部、水圈全部、岩石圈上部——其他圈层相互独立存在，只有生物圈的空间范围是「借住」在其他圈层之中的。", "kind": "self", "q": "四大外部圈层中，哪一个最「不独立」？说明它的空间范围与成因。"}, "apply": [{"ans": 1, "opts": ["大气圈", "水圈", "生物圈", "岩石圈"], "q": "横贯大气圈、水圈、岩石圈，渗透于各圈层之中的是（ ）", "why": "生物圈占据大气圈底部、水圈全部和岩石圈上部，是最活跃的圈层。"}, {"ans": 2, "opts": ["相互独立互不干扰", "相互联系、相互渗透", "只有单向影响关系", "仅在地表短暂接触"], "q": "地球外部圈层之间的关系是（ ）", "why": "四大圈层相互联系、相互渗透，共同构成人类赖以生存的自然环境。"}], "basics": [{"ans": 0, "opts": ["水圈", "大气圈", "生物圈", "岩石圈"], "q": "地球外部圈层中，处于不断循环运动之中、分布连续但不规则的是（ ）", "why": "水圈由各种水体组成，连续但不规则地分布，并处于循环运动中。"}, {"ans": 1, "opts": ["为生物提供氧气与适宜温度等生存条件", "提供岩浆活动能量", "直接形成所有地貌", "决定地震的分布"], "q": "大气圈对生命活动的主要意义是（ ）", "why": "大气提供氧气、水汽、保温与防护，是生命存在的必要条件之一。"}], "case": {"a": "水圈（水循环把大气水、地表水、地下水连起来）、生物圈（植物生长）、岩石圈（土壤与地形依托）、大气圈（降水与光照的来源背景）全部参与；核心圈层是水圈与岩石圈的交接——河流地貌正是水在岩石圈上作用的产物。", "hints": ["把材料中的每个要素（河、雨、林、地）逐个归圈层。", "「河流地貌」是关键词：它是水圈作用于岩石圈的结果。"], "q": "材料：某河流流域内，降水汇入河网冲刷两岸形成峡谷，河谷中森林茂盛、动物繁多。逐一指出材料中涉及的外部圈层，并选出两个关系最密切的圈层说明理由。", "steps": ["降水→大气圈；河流水体→水圈；峡谷地形、河岸→岩石圈；森林、动物→生物圈。四圈层全员到场。", "关系最密切：水圈与岩石圈——河流的侵蚀作用直接塑造了峡谷地貌。", "次密切：生物圈依托其余三圈层（水、土、气）而存在。"], "talk": ["圈层归属题逐词扫描：每个名词必属一圈，先归类再谈关系，最后点一对「作用—被作用」最直接的。"], "title": "案例：一个流域里数圈层"}, "intro": "地球表层是四个圈层套在一起的系统。==大气圈、水圈、岩石圈相对独立，生物圈最特殊：它渗透在其他三个圈层里，没有自己的独立空间。==这一节收尾全章：内部圈层看深度，外部圈层看联系。", "learn": [{"h": "四个外部圈层", "p": "**大气圈**：气体与悬浮物组成的包围层，提供氧气、保温防护。**水圈**：海洋、河流、湖泊、地下水、冰川等组成，连续但不规则，处在不断循环中。**岩石圈**：地壳与上地幔顶部（内部圈层课已学），是地貌与土壤的载体。**生物圈**：全部生物及其生存环境，占据大气圈底部、水圈全部、岩石圈上部。"}, {"h": "圈层之间的联系", "p": "圈层之间**相互联系、相互渗透、相互影响**：水循环同时穿过大气、水、岩石三圈；光合作用把大气圈的 CO₂ 变成生物圈的有机物；地貌演变是水圈、生物圈作用于岩石圈的结果。\n\n==综合题的命题方式就是给一段自然现象让你数圈层、说联系——先归类，后说作用关系。=="}, {"h": "易错提醒", "p": "易错提醒：岩石圈既是内部圈层的上部，又被列入外部圈层讨论（因为它与表层过程直接相关），两种语境下含义一致（地壳+上地幔顶部），不要以为是两个岩石圈。"}], "pitfalls": ["生物圈范围答成独立的一层。", "水圈答成「只有海洋」（河流、地下水、冰川都算）。"], "svg": "<circle cx='190' cy='70' r='52' fill='#e0f2fe'/><circle cx='165' cy='60' r='30' fill='#bae6fd' opacity='0.8'/><circle cx='215' cy='60' r='30' fill='#93c5fd' opacity='0.8'/><circle cx='190' cy='88' r='30' fill='#86efac' opacity='0.85'/><text x='190' y='66' text-anchor='middle' font-size='12'>生物圈</text><text x='190' y='84' text-anchor='middle' font-size='11'>渗透于气 · 水 · 岩</text><text x='70' y='40' font-size='12'>大气圈</text><text x='290' y='40' font-size='12'>水圈</text><text x='190' y='140' text-anchor='middle' font-size='12'>岩石圈（地表载体）</text>", "svgCap": "外部圈层：生物圈渗透在其他三圈之中，四圈相互联系。"}, "video": {"bvid": "BV1VCxQedEVW", "p": 9, "t": "1-4【辞典】地球的圈层结构", "dur": "27:57", "from": "一地er", "vtop": ["横波只能过固体：消失处之下是液态外核。", "岩石圈 = 地壳 + 上地幔顶部，不等于地壳。", "生物圈渗透于气、水、岩三圈，没有独立一层。"], "vsum": "第四节内外两分：内部靠**地震波**——==纵波快且穿三态、横波慢且只穿固体==；**莫霍面**（壳幔界）与**古登堡面**（幔核界，约 2900 千米、横波消失→外核液态）分出地壳、地幔、地核，软流层是岩浆发源地，**岩石圈**=地壳+上地幔顶部。外部四圈：大气圈、水圈（连续不规则）、岩石圈、生物圈（渗透于其余三圈），相互联系构成人类生存环境。视频为一地er《高中地理必修一基础与考点大合集》1-4【辞典】地球的圈层结构（27:57）。\n易错提醒：岩石圈不等于地壳，它还包括上地幔的顶部，两个概念答题时不能混用。", "vtech": ["看到波速图 → 找突变点定界面，找横波消失定液态。", "看到圈层归属题 → 逐词扫描归类，再找一对作用关系最直接的。", "看到岩石圈 → 立刻默念：地壳+上地幔顶部，不是地壳本身。"], "vgaokao": []}}, "geo_g009": {"name": "问题研究：火星基地应该是什么样子", "sec": 9, "secTitle": "问题研究", "page": null, "desc": "把生命条件框架反用在火星：能源、水、氧、防护、食物五大子系统设计。", "criteria": ["能复述本节核心概念与数据", "能看懂案例图表的判读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清判读依据"], "diag": null, "pre": ["geo_g002", "geo_g008"], "next": [], "content": {"advance": {"a": "优先：辐射与温控——先解决「活下去」（密封增压舱、地下或覆土选址屏蔽辐射、核能/太阳能供暖）；其次才是舒适性改造。理由是按生命条件框架排序：温度、气压（大气）、辐射防护是即时致命项，水与氧可靠技术系统持续供给。", "kind": "self", "q": "如果只能先解决火星基地的一个问题，你选哪个：供水、供氧、辐射防护、还是土壤改良？用生命条件框架说明排序理由。"}, "apply": [{"ans": 1, "opts": ["大气中有充足氧气", "有昼夜交替且周期与地球接近", "表面有大量液态水海洋", "气温常年高于 20 ℃"], "q": "火星与地球环境最相似的一点是（ ）", "why": "火星自转周期约 24 小时 37 分，有昼夜交替且接近地球；其余三项都不成立。"}, {"ans": 2, "opts": ["不需要任何防护即可居住", "必须解决辐射、温差与气压问题后才能长期居住", "改造火星土壤即可居住", "火星引力与地球相同所以没有障碍"], "q": "关于人类在火星建立基地，科学上正确的判断是（ ）", "why": "火星大气稀薄、辐射强、温差大，基地必须密闭增压并做辐射与温控防护。"}], "basics": [{"ans": 0, "opts": ["大气稀薄且以二氧化碳为主", "大气与地球完全相同", "没有大气", "大气中氧气含量高于地球"], "q": "火星大气的突出特点是（ ）", "why": "火星大气密度不到地球的 1%，以 CO₂ 为主，几乎没有游离氧。"}, {"ans": 1, "opts": ["两极地区存在水冰（及干冰）极冠", "地表河流纵横", "地下有与地球相同的淡水湖群（已确认）", "云层降水充沛"], "q": "火星上已知的水资源形式主要是（ ）", "why": "火星两极有水冰与干冰组成的极冠，地下也可能有冰层；地表无稳定液态水。"}], "case": {"a": "能源：太阳能（辅以核能）；水：开采极地或地下水冰；氧：电解水制氧；防护：选址地下/熔岩管或覆土建筑；食物：温室种植。五者以防护与能源为前提，水氧食为持续供给系统。", "hints": ["把问题拆成五个子系统：能源、水、氧、防护、食物。", "每个子系统先用火星本地条件找依据（如极冠冰→水）。"], "q": "为「火星基地应该是什么样子」列出设计清单：能源、水、氧气、辐射防护、食物五个方面各给出一个基于火星本地条件的方案。", "steps": ["能源：火星太阳辐射弱于地球，可用大面积太阳能阵列，辅以小型核能保底。", "水：开采两极极冠与地下水冰，基地内部全循环回收。", "氧气：电解水制氧（副产品氢可作燃料），远期用化学法分解 CO₂ 制氧。", "防护：基地主体埋入地下或利用熔岩管，墙体覆火星土壤屏蔽辐射与微陨石。", "食物：密闭温室水培/气雾栽培，利用火星光照周期安排补光。"], "talk": ["问题研究类课题用「子系统清单法」：把大问题拆成可逐个作答的子项，每项都要落回材料/本地条件，避免空想。"], "title": "案例：给火星基地列设计清单"}, "intro": "问题研究是把全章框架拿去实战：==火星基地应该是什么样子，本质是把「地球生命条件清单」反过来用在火星上——缺什么，就用什么技术补什么。==这一课不考背诵，考框架迁移。", "learn": [{"h": "火星与地球的相似与不同", "p": "相似：**自转周期接近**（约 24 小时 37 分，有昼夜交替）、有**四季变化**（公转与黄赤交角相近）、两极有**极冠**。不同：大气**稀薄**（不到地球 1%）且以 CO₂ 为主、无游离氧；表面平均温度约 **−63 ℃**、昼夜温差大；无全球磁场保护，**宇宙辐射强**；地表无稳定液态水。"}, {"h": "基地设计的五大子系统", "p": "**能源**（太阳能+核能兜底）、**水**（极冠/地下冰+全循环）、**氧气**（电解水或分解 CO₂ 制氧）、**防护**（地下选址、覆土屏蔽辐射、密闭增压）、**食物**（密闭温室种植）。\n\n==答问题研究题的方法：先摆火星的「先天条件」（有/无各列），再逐条给出「补法」，条件与对策一一对应。=="}, {"h": "易错提醒", "p": "易错提醒：火星「有四季」不等于「气候宜人」——四季来自公转与地轴倾斜，与温度是否适宜是两回事；火星太阳能可利用但强度弱于地球（距太阳更远），方案设计要留冗余。"}], "pitfalls": ["把「有昼夜/四季」误读为「环境与地球一样舒适」。", "方案只写愿望不写依据（不结合火星本地资源条件）。"], "svg": "<circle cx='90' cy='65' r='34' fill='#fca5a5'/><text x='90' y='70' text-anchor='middle' font-size='13'>火星</text><rect x='180' y='18' width='180' height='26' rx='6' fill='#e0f2fe'/><text x='270' y='35' text-anchor='middle' font-size='12'>能源：太阳能 + 核能</text><rect x='180' y='52' width='180' height='26' rx='6' fill='#e0f2fe'/><text x='270' y='69' text-anchor='middle' font-size='12'>水氧：采冰 · 电解制氧</text><rect x='180' y='86' width='180' height='26' rx='6' fill='#fee2e2'/><text x='270' y='103' text-anchor='middle' font-size='12'>防护：地下选址 · 覆土屏蔽</text><line x1='124' y1='50' x2='180' y2='35' stroke='#94a3b8'/><line x1='124' y1='65' x2='180' y2='66' stroke='#94a3b8'/><line x1='124' y1='80' x2='180' y2='97' stroke='#94a3b8'/>", "svgCap": "火星基地五大子系统：缺什么，补什么。"}, "video": {"bvid": "BV1uG4y1R7eR", "p": 1, "t": "问题研究：火星基地应该是什么样子", "dur": "9:26", "vtop": ["研究一个地方能不能住人：先摸清自然情况，再对生命保障条件", "火星像地球在距日、自转和轴倾角，不像在缺氧、严寒和沙尘暴", "基地靠生态生保系统循环再生氧气、水和食物，再按功能分区"], "vsum": "这节是问题研究，套路先摆明：收集资料摸清火星表面自然情况，再分析基地的**基本生命保障条件**，参考人类**受控生态生保系统**的研究成就，最后按功能设计并画构想图。火星表面：大气稀薄、**二氧化碳占95%以上**、温差极大（赤道夏季白天21℃、夜间零下73℃）、多沙尘暴；但也发现了干涸河床、两极干冰冰盖和地下**水冰**。==火星与地球相近的是距日距离、自转周期和自转轴倾角，又有大气层和不同形态的水，这是它成为移民首选的底气==；短板是缺氧、平均零下52℃严寒、没有液态水、辐射强、没有食物来源。我国**绿航星际**实验用植物舱、乘员舱、生保舱、资源舱协作，在封闭舱内实现氧气、水和部分食物的**循环再生**，正是基地的样板。最后按登陆区、居住区、科研区、能源区分区，从形态、功能、防护三方面出方案。\n易错提醒：别把「有大气层」答成「有氧气」——火星大气几乎全是二氧化碳，不能直接呼吸；它的水以冰的形式存在，也不是现成的液态水。", "vtech": [["看到「某星球适不适合建基地、住人」", "先按自然情况清单逐项对：大气成分、温度、水、辐射、能源，有利和不利分开列"], ["看到「需要改造哪些条件」", "对着短板反着写：缺氧就制氧造大气、严寒就保温、水是冰就取冰化水"], ["看到「参考某实验的借鉴意义」", "抓它实现了什么的循环再生（氧气、水、食物），对应到基地的生命保障系统"], ["看到「设计功能分区」", "每个区写清形态、功能、防护三件事，再用通道连成整体"]], "vgaokao": [], "from": "会打快板的地理老师"}}, "geo_g010": {"name": "大气的组成", "sec": 1, "secTitle": "大气的组成和垂直分层", "page": 28, "desc": "干洁空气成分表：氮 78%、氧 21%、CO₂ 与臭氧量少作用大；水汽与杂质是成云致雨的料与核。", "criteria": ["能复述本节核心概念与数据", "能看懂案例图表的判读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清判读依据"], "diag": null, "pre": [], "next": ["geo_g011"], "content": {"advance": {"a": "含量低不等于作用小：CO₂ 能吸收地面长波辐射，是大气保温作用的关键气体，其浓度变化会放大为地表热量收支的长期变化；臭氧含量更低，却决定了到达地面的紫外线强度。同理，微量成分的变化可以撬动整个系统，反驳的关键是「作用机制」而不是「含量比例」。", "kind": "self", "q": "有人说「二氧化碳只占大气的 0.04%，人类排放那一点不可能影响气候」。用本节知识反驳这一说法。"}, "apply": [{"ans": 1, "opts": ["到达地面的紫外线增多", "全球平均气温升高", "大气中氧气含量明显上升", "水汽凝结核增多"], "q": "大气中二氧化碳含量不断增加，最可能直接导致（ ）", "why": "CO₂ 吸收地面长波辐射、保温作用增强，是全球气候变暖的主要人为因素。"}, {"ans": 1, "opts": ["化石燃料燃烧排放二氧化碳", "制冷剂等释放氟氯碳化物", "汽车尾气排放氮氧化物", "建筑施工产生大量尘埃"], "q": "南极上空臭氧层空洞扩大的主要人为原因是（ ）", "why": "氟氯碳化物进入平流层后破坏臭氧；CO₂ 对应的是全球变暖，不要张冠李戴。"}], "basics": [{"ans": 1, "opts": ["氧气", "氮气", "二氧化碳", "氩气"], "q": "干洁空气中体积分数最大的成分是（ ）", "why": "氮气约占干洁空气体积的 78%，氧气约 21%。"}, {"ans": 2, "opts": ["二氧化碳", "水汽", "臭氧", "杂质"], "q": "被称为「地球生命的保护伞」、能吸收太阳紫外线的是（ ）", "why": "平流层的臭氧能大量吸收紫外线，保护地面生物。"}], "case": {"a": "二氧化碳是光合作用原料并吸收地面长波辐射起保温作用；臭氧吸收太阳紫外线，保护地球生命。两者含量极低，却分别卡在热量收支和辐射防护的关键位置。", "hints": ["先核对数据自洽：78%+21%+1%=100%，CO₂ 的 0.04% 包含在「其他 1%」之内。", "作用分别往两个方向找：CO₂ 往地面热量方向想，臭氧往太阳紫外线方向想。"], "q": "读图：干洁空气中氮气约 78%、氧气约 21%、其他气体约 1%；在「其他」中，二氧化碳约占总体积的 0.04%，臭氧更少。为什么说二氧化碳和臭氧是「含量最少、作用不小」的两种成分？各自的作用是什么？", "steps": ["数据核对：三大类体积分数合计 100%，CO₂ 与臭氧都属于含量极低的微量成分。", "二氧化碳：是光合作用的原料；能吸收地面长波辐射，对地面起保温作用——含量变化会牵动全球气温。", "臭氧：集中在平流层，能吸收太阳紫外线，保护地面生物免受强紫外线伤害。", "结论：判断一种成分重不重要，不能只看含量，要看它在能量与生命过程中的位置。"], "talk": ["组成图判读先做加法验算（各部分是否合计 100%），再逐成分对作用，这是图表题的固定两步。"], "title": "案例：读干洁空气组成图，找「量少作用大」的成分"}, "intro": "我们每一次呼吸，都在和整个大气圈交换物质。==大气是由**干洁空气**、**水汽**和**杂质**组成的混合物，其中干洁空气的体积分数以**氮气**约 78%、**氧气**约 21% 为绝对主体。==这一节先把成分表读准，再看每种成分各自管什么事。", "learn": [{"h": "干洁空气：四种成分各管一摊", "p": "**氮气**占干洁空气体积的 78%，是地球上生物体的基本成分（蛋白质的重要组成）。**氧气**占 21%，是人类和一切生物维持生命活动必需的物质。**二氧化碳**含量虽只有约 0.04%，却是绿色植物进行**光合作用**的原料，并能吸收地面长波辐射、起保温作用。**臭氧**含量极少，却能大量吸收太阳**紫外线**，被称为「地球生命的保护伞」。\n\n==成分题不能只背百分比：氮、氧看含量，CO₂ 和臭氧看「量少作用大」。=="}, {"h": "水汽和杂质：天气的原料", "p": "**水汽**的含量随时间和地点变化，是产生云、雨、雪等**天气现象**的必要条件（水汽凝结释放热量，还影响地面和大气的温度）。**杂质**（尘埃等固体微粒）是水汽的**凝结核**，没有它，水汽很难凝结成云滴。==记住一对关系：水汽提供「料」，杂质提供「核」，两者齐了才有成云致雨的条件。=="}, {"h": "人类活动正在改变大气成分", "p": "两条主线：①燃烧煤、石油等化石燃料和毁林，使大气中 **CO₂ 含量不断增加**，保温作用增强，导致全球气候变暖；②制冷剂等释放的**氟氯碳化物**破坏平流层臭氧，南极上空出现**臭氧层空洞**，到达地面的紫外线增多，危害人体健康与生态环境。易错提醒：臭氧在平流层是保护伞，但在近地面浓度过高反而是污染物，两种语境不要混。"}], "pitfalls": ["把 CO₂ 增多与臭氧空洞混为一谈（前者对应全球变暖，后者对应氟氯碳化物）。", "只背氮 78%、氧 21%，说不出 CO₂ 与臭氧的作用。", "漏掉水汽与杂质：成云致雨需要水汽（料）+凝结核（杂质）同时具备。"], "svg": "<circle cx='110' cy='70' r='52' fill='#dbeafe'/><path d='M110 70 L110 18 A52 52 0 1 1 58 88 Z' fill='#2563eb'/><text x='92' y='52' font-size='12' fill='#fff'>氮 78%</text><text x='128' y='105' font-size='12'>氧 21%</text><text x='205' y='40' font-size='12'>其他约 1%：</text><text x='205' y='60' font-size='11' fill='#475569'>氩、二氧化碳（约0.04%）、臭氧等</text><text x='205' y='88' font-size='12' fill='#b45309'>量少作用大：CO₂ 保温 · 臭氧吸紫外线</text>", "svgCap": "干洁空气组成（体积分数）：氮 78%、氧 21%、其他约 1%。"}, "video": {"bvid": "BV1VCxQedEVW", "p": 10, "t": "2-1【辞典】大气的组成和垂直分层", "dur": "53:02", "from": "一地er", "vtop": ["干洁空气：氮 78%、氧 21%，CO₂ 与臭氧量少作用大。", "分层依据是温度垂直变化：对流层、平流层、高层大气。", "对流层约 12 km（低纬 17—18、高纬 8—9），递减率约 0.6 ℃/100 m。"], "vsum": "第一节先认成分再分层：**干洁空气**中氮气约 78%（生物体基本成分）、氧气约 21%（维持生命活动），二氧化碳是光合作用原料并吸收地面长波辐射保温，臭氧吸收紫外线护生；水汽是天气现象的原料，杂质是**凝结核**。人类活动两笔账：化石燃料使 CO₂ 增多导致全球变暖，氟氯碳化物破坏臭氧形成空洞。==垂直分层依据温度垂直变化：对流层平均约 12 千米==（低纬 17—18、高纬 8—9），气温以约 0.6 ℃/100 m 递减、天气现象尽在其中；**平流层**（顶约 50—55 千米）因臭氧吸收紫外线而上热下冷、气流平稳，宜于飞行；高层大气的电离层能反射无线电短波。视频为一地er《高中地理必修一基础与考点大合集》2-1【辞典】大气的组成和垂直分层（53:02）。\n易错提醒：二氧化碳增多对应的是全球变暖，臭氧空洞是氟氯碳化物造成的，两件事不能混为一谈。", "vtech": ["看到成分作用题 → 先分含量派（氮、氧）与关键派（CO₂ 保温、臭氧吸紫外线），再落笔。", "看到气温曲线判层 → 先看增减方向，再用 0.6 ℃/100 m 验算变化率，最后对层名与成因。", "看到飞行/通信题 → 飞行找平流层（平稳少水汽），短波通信找电离层。"], "vgaokao": []}}, "geo_g011": {"name": "大气的垂直分层", "sec": 2, "secTitle": "大气的组成和垂直分层", "page": 30, "desc": "按温度垂直变化分三层：对流层约 12 km、递减率 0.6 ℃/100 m；平流层臭氧吸热宜飞行；电离层反射短波。", "criteria": ["能复述本节核心概念与数据", "能看懂案例图表的判读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清判读依据"], "diag": null, "pre": ["geo_g010"], "next": ["geo_g015"], "content": {"advance": {"a": "对流层厚度取决于对流运动的强弱：低纬地区地面受热多、空气对流旺盛，对流层顶被「顶」得更高（17—18 km）；高纬地区受热少、对流弱，厚度只有 8—9 km。影响：低纬对流层深厚，对流性天气（如雷暴）发展空间大、强度往往更强；高纬天气系统相对浅薄。答题链条是「受热差异→对流强弱→层顶高度」。", "kind": "self", "q": "为什么对流层的厚度低纬厚、高纬薄？这一差异对不同纬度的天气有什么影响？"}, "apply": [{"ans": 1, "opts": ["气温随高度递减，空气对流旺盛", "水汽、杂质极少，能见度高且气流平稳", "臭氧含量低，紫外线弱", "距地面近，节省燃料"], "q": "民航客机巡航高度多选在平流层，主要原因是平流层（ ）", "why": "平流层以水平运动为主、无天气现象、能见度好，飞行平稳安全。"}, {"ans": 2, "opts": ["对流层的云层反射", "平流层的臭氧反射", "高层大气中电离层的反射", "地面建筑物的反射"], "q": "地面无线电短波通信能实现远距离传输，依靠的是（ ）", "why": "高层大气中的电离层（约 60—500 km）能反射无线电短波。"}], "basics": [{"ans": 1, "opts": ["大气密度随高度的变化", "大气温度随高度的垂直变化", "大气运动状态的差异", "含氧量随高度的变化"], "q": "大气垂直分层的首要依据是（ ）", "why": "按温度垂直变化规律，大气自下而上分为对流层、平流层和高层大气。"}, {"ans": 1, "opts": ["随高度升高而升高", "随高度升高而降低，约 0.6 ℃/100 m", "不随高度变化", "先降后升"], "q": "对流层气温随高度变化的一般规律是（ ）", "why": "对流层热量主要来自地面，离地面越远得到的热量越少，平均每上升 100 米气温降低约 0.6 ℃。"}], "case": {"a": "0—12 km 为对流层，气温随高度递减，递减率约 0.6 ℃/100 m（与地面是热源、上冷下热利于对流相一致）；12—50 km 为平流层，气温随高度升高，因臭氧吸收紫外线增温。", "hints": ["先算 0—12 km：气温从 15 ℃降到 −57 ℃，共降 72 ℃，除以 12 km。", "12 km 以上气温由 −57 ℃回升到 −3 ℃，方向反过来了——分界就在这里。"], "q": "某地探空数据：地面（0 km）气温 15 ℃；6 km 处 −21 ℃；12 km 处 −57 ℃；30 km 处 −40 ℃；50 km 处 −3 ℃。①0—12 km 气温变化的规律是什么？平均每千米降低多少？这一层叫什么？②12—50 km 气温又怎样变化？这一层叫什么？增温的主要原因是什么？", "steps": ["0—12 km：气温随高度升高而降低，12 km 共降低 72 ℃，平均每千米降低 6 ℃，即每 100 米降低 0.6 ℃，与对流层的递减率一致——这一层是对流层。", "12—50 km：气温随高度升高而升高（−57 ℃→−3 ℃），这一层是平流层。", "平流层增温的主要原因是臭氧吸收太阳紫外线，把辐射能转化为热能。", "两层分界（对流层顶）约在 12 km，与对流层平均厚度吻合，数据自洽。"], "talk": ["气温曲线判读三步：先看每一段的增减方向，再算变化率核对 0.6 ℃/100 m，最后把方向和层名、成因对上号。"], "title": "案例：读气温垂直变化数据，判层与算温"}, "intro": "从地面向上几千千米，大气并不是均匀的一团。==科学家依据**大气温度随高度的垂直变化**，自下而上把大气分为**对流层**、**平流层**和**高层大气**三层。==哪一层发生天气、哪一层适合飞机飞行、哪一层能反射无线电波，全看这一节的分层图。", "learn": [{"h": "对流层：天气的发生地", "p": "**对流层**紧贴地面，平均厚度约 **12 千米**（低纬度约 17—18 千米、中纬度 10—12 千米、高纬度仅 8—9 千米）。气温随高度升高而**递减**，平均每上升 100 米降低约 **0.6 ℃**。大气中几乎全部的**水汽和杂质**都集中在这一层，空气**对流运动**显著，云、雨、雪等天气现象都发生在这里。\n\n==对流层抓三个词：厚度因纬度而异、气温上冷下热、天气都在这一层。=="}, {"h": "平流层：飞机的巡航层", "p": "**平流层**位于对流层之上，顶界约在 50—55 千米高空。**臭氧层**主要分布在这一层（约 15—35 千米处臭氧相对集中），臭氧吸收紫外线使气温随高度升高而**升高**，大气以**水平运动**（平流）为主，几乎没有水汽和杂质，天气晴朗、能见度高。==气温上热下冷、空气不翻腾，所以平流层是民航飞机最理想的飞行层。=="}, {"h": "高层大气：无线电的镜子", "p": "平流层以上是**高层大气**，顶界可达 2000—3000 千米，空气极其稀薄。其中 60—500 千米高空有若干**电离层**，大气在太阳紫外线和宇宙射线作用下处于电离状态，能反射**无线电短波**，对地面无线电短波通信有重要作用。易错提醒：分层的首要依据是温度的垂直变化规律，其次才联系密度、运动状态等特征，答「划分依据」只答温度这一条。"}], "pitfalls": ["划分依据答成密度或运动（首要依据是温度垂直变化）。", "对流层厚度只记 12 km 平均数，忘了低纬 17—18 km、高纬 8—9 km 的纬度差异。", "臭氧层位置记错层（在平流层，不在对流层或高层大气）。"], "svg": "<rect x='120' y='8' width='150' height='34' rx='4' fill='#e0f2fe'/><text x='195' y='30' text-anchor='middle' font-size='12'>高层大气（电离层反射短波）</text><rect x='120' y='48' width='150' height='34' rx='4' fill='#bae6fd'/><text x='195' y='70' text-anchor='middle' font-size='12'>平流层（臭氧层 · 气温↑）</text><rect x='120' y='88' width='150' height='34' rx='4' fill='#60a5fa'/><text x='195' y='110' text-anchor='middle' font-size='12' fill='#fff'>对流层（天气 · 气温↓）</text><text x='55' y='70' font-size='11'>约50—55 km</text><text x='55' y='110' font-size='11'>约12 km</text><text x='330' y='70' font-size='11' fill='#64748b'>地面 0 km</text>", "svgCap": "大气垂直分层：界线高度、对流层约 12 km、平流层顶约 50—55 km。"}, "video": {"bvid": "BV1VCxQedEVW", "p": 10, "t": "2-1【辞典】大气的组成和垂直分层", "dur": "53:02", "from": "一地er", "vtop": ["干洁空气：氮 78%、氧 21%，CO₂ 与臭氧量少作用大。", "分层依据是温度垂直变化：对流层、平流层、高层大气。", "对流层约 12 km（低纬 17—18、高纬 8—9），递减率约 0.6 ℃/100 m。"], "vsum": "第一节先认成分再分层：**干洁空气**中氮气约 78%（生物体基本成分）、氧气约 21%（维持生命活动），二氧化碳是光合作用原料并吸收地面长波辐射保温，臭氧吸收紫外线护生；水汽是天气现象的原料，杂质是**凝结核**。人类活动两笔账：化石燃料使 CO₂ 增多导致全球变暖，氟氯碳化物破坏臭氧形成空洞。==垂直分层依据温度垂直变化：对流层平均约 12 千米==（低纬 17—18、高纬 8—9），气温以约 0.6 ℃/100 m 递减、天气现象尽在其中；**平流层**（顶约 50—55 千米）因臭氧吸收紫外线而上热下冷、气流平稳，宜于飞行；高层大气的电离层能反射无线电短波。视频为一地er《高中地理必修一基础与考点大合集》2-1【辞典】大气的组成和垂直分层（53:02）。\n易错提醒：二氧化碳增多对应的是全球变暖，臭氧空洞是氟氯碳化物造成的，两件事不能混为一谈。", "vtech": ["看到成分作用题 → 先分含量派（氮、氧）与关键派（CO₂ 保温、臭氧吸紫外线），再落笔。", "看到气温曲线判层 → 先看增减方向，再用 0.6 ℃/100 m 验算变化率，最后对层名与成因。", "看到飞行/通信题 → 飞行找平流层（平稳少水汽），短波通信找电离层。"], "vgaokao": []}}, "geo_g012": {"name": "大气受热过程与保温作用", "sec": 3, "secTitle": "大气受热过程和大气运动", "page": 34, "desc": "三段链：太阳暖大地、大地暖大气、大气还大地；削弱与保温解释温差、霜冻与温室大棚。", "criteria": ["能复述本节核心概念与数据", "能看懂案例图表的判读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清判读依据"], "diag": null, "pre": [], "next": ["geo_g013", "geo_g015"], "content": {"advance": {"a": "月球几乎没有大气：白天没有削弱作用，太阳辐射长驱直入，表面升温极高；夜晚没有大气吸收地面辐射、更没有大气逆辐射还热，热量全部散失到宇宙空间，温度骤降。地球有大气，白天削弱作用挡掉一部分辐射，夜晚大气逆辐射把热量还给地面，一挡一还之间，昼夜温差被大幅压缩。对比题的得分点正是「有/无大气→削弱与保温有/无」这条链。", "kind": "self", "q": "月球表面昼夜温差高达 300 ℃以上，而地球表面昼夜温差要小得多。用大气受热过程完整解释这一差异。"}, "apply": [{"ans": 0, "opts": ["水汽少，白天削弱弱、夜间逆辐射弱", "太阳辐射总量比海洋少", "地面辐射全部被反射", "风速大，热量散失快"], "q": "沙漠地区昼夜温差远大于沿海湿润地区，主要原因是沙漠上空（ ）", "why": "沙漠空气干燥、晴天多：白天削弱作用弱、升温猛；夜间大气逆辐射弱、降温快，一猛一快拉出大温差。"}, {"ans": 1, "opts": ["增强太阳辐射", "增强大气逆辐射，减轻地面降温", "反射地面辐射回大气层顶部", "增加地面反射率"], "q": "秋冬季节，我国北方农民常用人造烟幕防御霜冻，原理是烟幕能（ ）", "why": "烟幕增加大气中尘粒与水汽，增强大气逆辐射，对地面起保温作用，减轻霜冻危害。"}], "basics": [{"ans": 1, "opts": ["太阳辐射", "地面辐射", "大气逆辐射", "太阳短波辐射的吸收"], "q": "对流层大气增温的直接热源是（ ）", "why": "大气对太阳短波辐射吸收很少，却强烈吸收地面长波辐射，地面是对流大气的主要直接热源。"}, {"ans": 1, "opts": ["削弱作用", "大气逆辐射", "散射作用", "反射作用"], "q": "大气对地面的保温作用是通过（ ）实现的", "why": "大气逆辐射把热量返还地面，补偿地面辐射损失的热量，起保温作用。"}], "case": {"a": "白天云层削弱作用强使阴天升温少；夜间云层使大气逆辐射强、保温好使阴天降温少；两者共同造成阴天昼夜温差小。", "hints": ["白天比的是「进来的少了」——云层的削弱作用；夜间比的是「出去的少了」——大气逆辐射。", "两个时段各用一个作用，合起来正好把温差从 14 ℃压到 6 ℃。"], "q": "某地连续两日实测：晴天白天最高气温 32 ℃、夜间最低 18 ℃，昼夜温差 14 ℃；阴天白天最高 27 ℃、夜间最低 21 ℃，昼夜温差 6 ℃。分别从白天和夜间两个时段，用大气受热过程解释为什么阴天昼夜温差比晴天小。", "steps": ["白天：阴天云层厚，对太阳辐射的反射等削弱作用强，到达地面的太阳辐射少，地面增温少，所以白天最高气温比晴天低 5 ℃（27 ℃对 32 ℃）。", "夜间：阴天云层厚（水汽、尘粒多），大气吸收地面长波辐射多，大气逆辐射强，对地面的保温作用强，地面降温慢，所以夜间最低气温比晴天高 3 ℃（21 ℃对 18 ℃）。", "一低一高，两头夹击：阴天昼夜温差（6 ℃）明显小于晴天（14 ℃），数据与机制完全对应。"], "talk": ["温差类题固定双段结构：白天答削弱、夜间答保温（逆辐射），缺一段就丢一半分。"], "title": "案例：用受热过程解释一张昼夜温差表"}, "intro": "白天太阳晒得地面发烫，夜里地面又把热量还给天空。==大气受热过程只有三句话：**太阳暖大地、大地暖大气、大气还大地**。==昼夜温差、秋夜霜冻、温室大棚，全是这三句话的应用题。", "learn": [{"h": "第一段：太阳暖大地——先过削弱这一关", "p": "太阳辐射是**短波辐射**，穿过大气时先被**削弱作用**（**吸收、反射、散射**）削去一部分：臭氧吸收紫外线、水汽和 CO₂ 吸收红外线，云层和颗粒物反射，空气分子散射。到达地面的太阳辐射被地面吸收，地面增温。\n\n==云越厚、削弱越强，到达地面的太阳辐射越少——这是阴天白天不热的根本原因。=="}, {"h": "第二段：大地暖大气——地面才是对流层的热源", "p": "地面吸收太阳辐射后以**地面辐射**（**长波辐射**）的形式向外放热；大气中的水汽、CO₂ 强烈吸收地面长波辐射，大气增温。所以**对流层大气的直接热源是地面**，离地面越远气温越低（呼应 0.6 ℃/100 m 的递减率）。==考试问「大气热量主要来自哪里」，答案永远是地面辐射，不是太阳辐射。=="}, {"h": "第三段：大气还大地——保温作用与三个经典解释", "p": "大气增温后以**大气辐射**向四面放热，其中射向地面的部分叫**大气逆辐射**，它把热量还给地面，起**保温作用**。三个经典解释：①**昼夜温差**：白天云多削弱强、夜里云多逆辐射强，所以阴天昼夜温差小；晴天则相反，温差大。②**霜冻**：秋冬晴朗夜晚，大气逆辐射弱，地面降温剧烈，水汽凝结成霜。③**温室大棚**：玻璃（或塑料膜）允许太阳短波辐射透入，又阻止棚内地面长波辐射散失，与大气的保温作用原理相同。"}], "pitfalls": ["把大气的直接热源答成太阳辐射（正确是地面辐射）。", "解释温差只答白天或只答夜间，漏掉削弱与保温中的一段。", "霜冻题答反：晴朗夜晚逆辐射弱才易出现霜冻，阴天夜晚反而不易。"], "svg": "<circle cx='60' cy='22' r='14' fill='#fbbf24'/><text x='60' y='48' text-anchor='middle' font-size='11'>太阳辐射↓（短波）</text><line x1='150' y1='15' x2='150' y2='95' stroke='#f59e0b' stroke-width='3'/><polygon points='144,88 156,88 150,100' fill='#f59e0b'/><line x1='215' y1='100' x2='215' y2='30' stroke='#dc2626' stroke-width='3'/><polygon points='209,37 215,25 221,37' fill='#dc2626'/><text x='215' y='18' text-anchor='middle' font-size='11'>地面辐射↑（长波）</text><line x1='280' y1='30' x2='280' y2='100' stroke='#2563eb' stroke-width='3' stroke-dasharray='5 3'/><polygon points='274,93 280,105 286,93' fill='#2563eb'/><text x='285' y='18' text-anchor='middle' font-size='11'>大气逆辐射↓还大地</text><rect x='90' y='104' width='220' height='12' fill='#92400e'/><text x='200' y='130' text-anchor='middle' font-size='12'>地面：太阳暖大地 → 大地暖大气 → 大气还大地</text>", "svgCap": "大气受热过程三段箭头：太阳辐射（短波）入、地面辐射（长波）出、大气逆辐射还。"}, "video": {"bvid": "BV1VCxQedEVW", "p": 12, "t": "2-2【辞典】大气的受热过程", "dur": "79:04", "from": "一地er", "vtop": ["受热三段：太阳暖大地、大地暖大气、大气还大地（逆辐射）。", "热力环流：热升低压、冷沉高压，高空与近地面气压相反。", "风的判读：先垂（梯度力）后偏（北右南左），高空平行、近地斜穿。"], "vsum": "第二节是一条能量—运动链：受热过程三段（太阳暖大地—削弱作用之后的短波到达地面；大地暖大气—==地面长波辐射是对流层大气的直接热源==；大气还大地—**大气逆辐射**起保温作用），用它解释阴天温差小、晴夜易霜冻、温室大棚保温。**热力环流**由冷热不均发动：热处上升成近地面低压、冷处下沉成近地面高压，高空相反，风由高压吹向低压；海陆风昼夜倒向、山谷风昼夜倒坡、城市风由郊吹城，都是同一环流。风的形成看三力：**水平气压梯度力**是原动力（等压线越密风越大），**地转偏向力**北右南左只改方向，摩擦力减速并使风向斜穿等压线；高空风平行等压线，近地面风斜交，风压定律可验算方向。视频为一地er《高中地理必修一基础与考点大合集》2-2【辞典】大气的受热过程（79:04）；热力环流与风的辞典在同合集紧接着的两集里。\n易错提醒：对流层大气的直接热源是地面辐射而不是太阳辐射，这是本节最容易答错的一点。", "vtech": ["看到昼夜温差题 → 双段答：白天削弱、夜间逆辐射保温，缺一段丢一半。", "看到局地风判向 → 先比冷热定升沉，再定近地面气压，最后风从高压吹向低压。", "看到等压线图 → 先看疏密定风速，再画梯度力（垂、向低），最后按半球偏转并用风压定律验算。"], "vgaokao": []}}, "geo_g013": {"name": "热力环流", "sec": 4, "secTitle": "大气受热过程和大气运动", "page": 38, "desc": "四步成环：冷热不均→升沉→气压差→风；海陆风、山谷风、城市热岛环流同理同判。", "criteria": ["能复述本节核心概念与数据", "能看懂案例图表的判读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清判读依据"], "diag": null, "pre": ["geo_g012"], "next": ["geo_g014"], "content": {"advance": {"a": "近地面低压对应空气上升，上升过程中气温降低、水汽易凝结成云致雨；近地面高压对应空气下沉，下沉增温、水汽难以凝结，天气晴朗。到了高空，气压高低与升沉的对应关系恰好反过来（上升区的高空是高压、却不是下沉），且高空水汽极少，谈不上用同一逻辑判天气——所以这句话只适用于近地面，且本质是垂直运动决定天气，气压只是表象。", "kind": "self", "q": "为什么说「高压处天气晴朗、低压处多阴雨」在近地面大体成立？用热力环流的垂直运动解释，并指出这一说法在高空为什么不适用。"}, "apply": [{"ans": 1, "opts": ["山风，沿坡下沉吹向谷底", "谷风，沿坡上升吹向山坡", "海风，吹向山坡", "陆风，吹向谷底"], "q": "白天，山坡与同高度的谷底空气相比，山坡空气温度较高，由此形成的局地风是（ ）", "why": "白天山坡受热快，空气沿坡上升，谷底空气沿山坡爬升补充，形成谷风。"}, {"ans": 1, "opts": ["城市中心区", "城市热岛环流范围之外的下风向/远离回流路径处", "郊区风吹向城市的路径上", "城市河流上游的中心地带"], "q": "为减少城市热岛环流把污染物带回城区，重污染工厂最宜布局在（ ）", "why": "近地面风由郊区吹向城市，工厂若建在环流范围内，污染物会随回流进入城区，应布局在环流范围之外。"}], "basics": [{"ans": 1, "opts": ["地转偏向力", "地面冷热不均", "海陆分布差异", "地形起伏"], "q": "形成热力环流的根本原因是（ ）", "why": "地面冷热不均引起空气升降，进而造成气压差异与水平运动，这是热力环流的根本原因。"}, {"ans": 2, "opts": ["受热地区近地面形成高压", "受冷地区近地面形成低压", "高空与近地面的气压状况相反", "同一地点高空与近地面气压始终相等"], "q": "关于热力环流中气压的叙述，正确的是（ ）", "why": "受热上升→近地面低压、高空高压；受冷下沉→近地面高压、高空低压，高空与近地面恰好相反。"}], "case": {"a": "近地面吹海风（海→陆）；高空空气由陆地上空流向海洋上空；环流为陆升—高空陆向海—海沉—近地面海向陆。", "hints": ["近地面谁的气压低，风就吹向谁：风从高压（1006）吹向低压（1002）。", "高空的气压分布与近地面相反，这是环流闭合的关键。"], "q": "夏季某日午后，沿海测站数据：陆地近地面气压 1002 hPa、气温 33 ℃；海洋近地面气压 1006 hPa、海水温度 26 ℃；同一高度的高空水平面上，陆地上空气压相对较高、海洋上空相对较低。①此时近地面吹海风还是陆风？②高空空气怎样流动？③画出（说出）这个环流的完整路径。", "steps": ["陆地气温高（33 ℃），空气受热上升，近地面形成低压（1002 hPa）；海洋较冷，空气下沉，近地面高压（1006 hPa）。", "近地面空气由海洋（高压）流向陆地（低压），即午后吹海风，与夏季午后实际一致。", "高空：陆地上空空气堆积形成相对高压、海洋上空相对低压，空气由陆地上空流向海洋上空，与近地面风向相反。", "完整环流：陆地上升→高空陆→海→海洋下沉→近地面海→陆，闭合。"], "talk": ["热力环流判读先定冷热、再定升沉、再定气压、最后定风向，四步顺序不能颠倒；看到高空气压要记得与近地面反着读。"], "title": "案例：读海陆气压数据判海风与高空风向"}, "intro": "地面受热不均，大气就会自己转起圈来。==**热力环流**的因果链只有四步：冷热不均→空气垂直运动→同一水平面气压差异→空气水平运动（风）。==海陆风、山谷风、城市风，都是这条链换了个场景在重演。", "learn": [{"h": "四步成环：从冷热不均到风", "p": "受热多的地方空气膨胀**上升**，近地面形成**低压**、高空形成高压；受冷的地方空气收缩**下沉**，近地面形成**高压**、高空形成低压。于是同一水平面上有了气压差，空气由高压流向低压，环流闭合。\n\n==口诀：热升冷沉；近地面热低压、冷高压；高空与近地面气压状况恰好相反。==注意：这里的「高压、低压」都是同一水平面相比较而言的。"}, {"h": "海陆风：一天倒两次向", "p": "白天陆地升温快（热源），空气上升、近地面形成低压，海洋相对较冷形成高压，近地面风从海洋吹向陆地，叫**海风**；夜晚陆地降温快形成高压，海洋相对温暖形成低压，风从陆地吹向海洋，叫**陆风**。判读抓手：先比海陆谁热谁冷，再套「热低压、风从高压吹向低压」。"}, {"h": "山谷风与城市风：同一原理的两个分身", "p": "**山谷风**：白天山坡受热快，空气沿坡上升，风从谷底吹向山坡（**谷风**）；夜晚山坡降温快，冷空气沿坡下沉吹向谷底（**山风**）。**城市热岛环流**：城市气温比郊区高，城市空气上升，近地面风由郊区吹向城市——所以有污染的工厂应布局在城市热岛环流范围之外，避免污染物被风带回城区。\n\n易错提醒：山谷风的风向看的是「山坡与谷底（同高度空气）的温差」，不是山顶与谷底的地形高差。"}], "pitfalls": ["把高空气压与近地面气压读成同高同低（实际相反）。", "海陆风只记名称不记成因：判风先比冷热，白天陆热、夜里陆冷。", "山风、谷风方向记反：白天谷风上坡、夜晚山风下坡。"], "svg": "<rect x='20' y='95' width='150' height='18' fill='#f59e0b'/><text x='95' y='88' text-anchor='middle' font-size='12'>陆地（热 · 低压）</text><rect x='220' y='95' width='150' height='18' fill='#38bdf8'/><text x='295' y='88' text-anchor='middle' font-size='12'>海洋（冷 · 高压）</text><path d='M95 90 L95 35' stroke='#dc2626' stroke-width='3'/><polygon points='89,42 95,28 101,42' fill='#dc2626'/><path d='M295 35 L295 90' stroke='#2563eb' stroke-width='3'/><polygon points='289,83 295,97 301,83' fill='#2563eb'/><path d='M100 30 L290 30' stroke='#475569' stroke-width='2'/><polygon points='282,24 296,30 282,36' fill='#475569'/><path d='M290 108 L100 108' stroke='#475569' stroke-width='2'/><polygon points='108,102 94,108 108,114' fill='#475569'/><text x='195' y='22' text-anchor='middle' font-size='11'>高空：陆 → 海</text><text x='195' y='132' text-anchor='middle' font-size='11'>近地面：海风（海 → 陆）</text>", "svgCap": "白天海陆热力环流：陆热升、洋冷沉，近地面吹海风，高空风向相反。"}, "video": {"bvid": "BV1VCxQedEVW", "p": 12, "t": "2-2【辞典】大气的受热过程", "dur": "79:04", "from": "一地er", "vtop": ["受热三段：太阳暖大地、大地暖大气、大气还大地（逆辐射）。", "热力环流：热升低压、冷沉高压，高空与近地面气压相反。", "风的判读：先垂（梯度力）后偏（北右南左），高空平行、近地斜穿。"], "vsum": "第二节是一条能量—运动链：受热过程三段（太阳暖大地—削弱作用之后的短波到达地面；大地暖大气—==地面长波辐射是对流层大气的直接热源==；大气还大地—**大气逆辐射**起保温作用），用它解释阴天温差小、晴夜易霜冻、温室大棚保温。**热力环流**由冷热不均发动：热处上升成近地面低压、冷处下沉成近地面高压，高空相反，风由高压吹向低压；海陆风昼夜倒向、山谷风昼夜倒坡、城市风由郊吹城，都是同一环流。风的形成看三力：**水平气压梯度力**是原动力（等压线越密风越大），**地转偏向力**北右南左只改方向，摩擦力减速并使风向斜穿等压线；高空风平行等压线，近地面风斜交，风压定律可验算方向。视频为一地er《高中地理必修一基础与考点大合集》2-2【辞典】大气的受热过程（79:04）；热力环流与风的辞典在同合集紧接着的两集里。\n易错提醒：对流层大气的直接热源是地面辐射而不是太阳辐射，这是本节最容易答错的一点。", "vtech": ["看到昼夜温差题 → 双段答：白天削弱、夜间逆辐射保温，缺一段丢一半。", "看到局地风判向 → 先比冷热定升沉，再定近地面气压，最后风从高压吹向低压。", "看到等压线图 → 先看疏密定风速，再画梯度力（垂、向低），最后按半球偏转并用风压定律验算。"], "vgaokao": []}}, "geo_g014": {"name": "大气的水平运动：风", "sec": 5, "secTitle": "大气受热过程和大气运动", "page": 41, "desc": "三力分工：梯度力是原动力、偏向力只拐弯、摩擦力减速斜穿；高空平行、近地面斜交等压线。", "criteria": ["能复述本节核心概念与数据", "能看懂案例图表的判读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清判读依据"], "diag": null, "pre": ["geo_g013"], "next": [], "content": {"advance": {"a": "梯度力不变：仍垂直等压线、由南侧高压指向北侧低压。但南半球地转偏向力使风向左偏：近地面风斜穿等压线、由东南吹向西北，按来向命名为东南风；与北半球的西南风恰好关于梯度力方向（正北）镜像对称。推理要点：换半球只换偏转方向，梯度力与摩擦力的作用方式不变。", "kind": "self", "q": "南半球一架飞机的航线下方是开阔海洋（近地面），气压场与本节案例相同（北低南高、等压线东西向）。与北半球相比，该地近地面风向会有什么不同？说明推理过程。"}, "apply": [{"ans": 1, "opts": ["气压更高", "风速更大", "气温更低", "地转偏向力更大"], "q": "同一幅等压线图中，甲处等压线比乙处密集，则甲处（ ）", "why": "等压线越密集，水平气压梯度越大，梯度力越大，风速越大。"}, {"ans": 2, "opts": ["右方", "右前方", "左前方", "正后方"], "q": "北半球近地面，背风而立时，低压所在的方向是（ ）", "why": "风压定律（北半球近地面）：背风而立，低压在左前方、高压在右后方；高空则低压在正左方。"}], "basics": [{"ans": 2, "opts": ["地转偏向力", "摩擦力", "水平气压梯度力", "重力"], "q": "形成风的原动力是（ ）", "why": "水平气压梯度力垂直于等压线、由高压指向低压，是空气水平运动的原动力。"}, {"ans": 1, "opts": ["垂直", "平行", "斜交且指向低压一侧", "斜交且指向高压一侧"], "q": "北半球高空风的风向最终与等压线（ ）", "why": "高空摩擦力可忽略，梯度力与地转偏向力平衡时，风向与等压线平行。"}], "case": {"a": "甲地风速大于乙地（等压线密集、梯度力大）；高空风与等压线平行、自西向东；近地面风斜穿等压线吹向东北，为西南风。", "hints": ["风速只看疏密，与气压绝对值大小无关。", "先画梯度力（垂直等压线、南高→北低，即指向北），再右偏：高空偏到平行，近地面偏到斜交。"], "q": "北半球某等压线图：等压线呈东西向分布，北侧为 1000 hPa 低压、南侧为 1015 hPa 高压；甲地等压线密集，乙地等压线稀疏。①甲、乙两地哪地风速大？为什么？②在图中某点画高空风向：方向如何？③同一点近地面风向与高空有何不同？该点近地面吹什么风（按来向命名）？", "steps": ["甲地等压线密集，单位距离气压差（气压梯度）大，水平气压梯度力大，风速大于乙地。", "梯度力方向：垂直于等压线，由南侧高压指向北侧低压（指向正北）。", "高空：只受梯度力与地转偏向力，北半球右偏直至与等压线平行——风向自西向东（西风），此时低压（北侧）在风向的左侧，符合风压定律。", "近地面：受摩擦力影响，右偏幅度减小，风向斜穿等压线、由西南吹向东北，按来向命名为西南风；背风而立时低压在左前方，与风压定律一致。"], "talk": ["风向判读口诀：先垂（梯度力）后偏（右/左偏），高空偏平、近地偏斜；最后用风压定律验算一遍，方向错没错立刻见分晓。"], "title": "案例：读等压线图，判风速与风向"}, "intro": "风不是凭空来的，是气压差推出来的。==近地面的风受三个力拉扯：**水平气压梯度力**（动力的源头）、**地转偏向力**（只改方向）、**摩擦力**（减速又改向）；高空少了摩擦力，风向就与等压线平行。==这一节是全章判图分最重的一节：等压线图怎么读、风向怎么画，全在这里。", "learn": [{"h": "三个力：一个出力、一个拐弯、一个拖后腿", "p": "**水平气压梯度力**：垂直于**等压线**、由高压指向低压，是形成风的**原动力**；等压线越密集，气压梯度越大，风速越大。**地转偏向力**：与风向垂直，**北半球右偏、南半球左偏**，只改变风向、不改变风速。**摩擦力**：方向与风向相反，既减小风速，也使风向偏离等压线。\n\n==记力先记分工：梯度力管「有没有风、多大风」，偏向力管「往哪偏」，摩擦力管「减多少、斜多少」。=="}, {"h": "两种风：高空平行、近地面斜穿", "p": "**高空风**只受梯度力与偏向力，两力平衡时风向与等压线**平行**。**近地面风**多受摩擦力，风向与等压线**斜交**，由高压吹向低压。**风压定律**（北半球）：高空背风而立，低压在左、高压在右；近地面背风而立，低压在左前方、高压在右后方。南半球则相反（左偏）。"}, {"h": "等压线图判读三步", "p": "第一步看疏密：**等压线密集处风大、稀疏处风小**。第二步定梯度力：垂直于等压线、高压指向低压画出箭头。第三步偏转：北半球在梯度力方向基础上右偏（高空偏到与等压线平行，近地面偏约 30°—45° 斜穿等压线），南半球左偏。易错提醒：风向指的是风的**来向**（如北风就是从北吹向南），画箭头时箭头指向风的去向，别把命名方向画反。"}], "pitfalls": ["风向命名画反：北风是从北向南吹，箭头应指向南。", "把地转偏向力当成动力（它只改方向、不改风速，更不是风的成因）。", "高空与近地面风向混淆：平行是高空，斜穿是近地面。"], "svg": "<line x1='30' y1='30' x2='360' y2='30' stroke='#94a3b8'/><text x='368' y='34' font-size='11'>1000</text><line x1='30' y1='60' x2='360' y2='60' stroke='#94a3b8'/><text x='368' y='64' font-size='11'>1005</text><line x1='30' y1='90' x2='360' y2='90' stroke='#94a3b8'/><text x='368' y='94' font-size='11'>1010</text><line x1='30' y1='120' x2='360' y2='120' stroke='#64748b'/><text x='368' y='124' font-size='11'>1015 高压</text><text x='40' y='20' font-size='11'>北侧低压 · 等压线（hPa）</text><path d='M110 118 L172 52' stroke='#dc2626' stroke-width='3'/><polygon points='164,44 180,46 172,60' fill='#dc2626'/><text x='120' y='140' font-size='11' fill='#dc2626'>近地面风：斜穿等压线（西南风）</text><path d='M250 88 L315 88' stroke='#2563eb' stroke-width='3'/><polygon points='307,81 322,88 307,95' fill='#2563eb'/><text x='250' y='75' font-size='11' fill='#2563eb'>高空风：平行等压线（西风）</text>", "svgCap": "北半球等压线图（北低南高）：高空风平行等压线自西向东，近地面风斜穿等压线吹向低压。"}, "video": {"bvid": "BV1VCxQedEVW", "p": 12, "t": "2-2【辞典】大气的受热过程", "dur": "79:04", "from": "一地er", "vtop": ["受热三段：太阳暖大地、大地暖大气、大气还大地（逆辐射）。", "热力环流：热升低压、冷沉高压，高空与近地面气压相反。", "风的判读：先垂（梯度力）后偏（北右南左），高空平行、近地斜穿。"], "vsum": "第二节是一条能量—运动链：受热过程三段（太阳暖大地—削弱作用之后的短波到达地面；大地暖大气—==地面长波辐射是对流层大气的直接热源==；大气还大地—**大气逆辐射**起保温作用），用它解释阴天温差小、晴夜易霜冻、温室大棚保温。**热力环流**由冷热不均发动：热处上升成近地面低压、冷处下沉成近地面高压，高空相反，风由高压吹向低压；海陆风昼夜倒向、山谷风昼夜倒坡、城市风由郊吹城，都是同一环流。风的形成看三力：**水平气压梯度力**是原动力（等压线越密风越大），**地转偏向力**北右南左只改方向，摩擦力减速并使风向斜穿等压线；高空风平行等压线，近地面风斜交，风压定律可验算方向。视频为一地er《高中地理必修一基础与考点大合集》2-2【辞典】大气的受热过程（79:04）；热力环流与风的辞典在同合集紧接着的两集里。\n易错提醒：对流层大气的直接热源是地面辐射而不是太阳辐射，这是本节最容易答错的一点。", "vtech": ["看到昼夜温差题 → 双段答：白天削弱、夜间逆辐射保温，缺一段丢一半。", "看到局地风判向 → 先比冷热定升沉，再定近地面气压，最后风从高压吹向低压。", "看到等压线图 → 先看疏密定风速，再画梯度力（垂、向低），最后按半球偏转并用风压定律验算。"], "vgaokao": []}}, "geo_g015": {"name": "问题研究：大气污染与蓝天保卫战", "sec": 6, "secTitle": "问题研究：何时蓝天常在", "page": null, "desc": "雾霾成因链：排放（内因）×逆温静风（外因）；防治措施逐环对应污染源与扩散条件。", "criteria": ["能复述本节核心概念与数据", "能看懂案例图表的判读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清判读依据"], "diag": null, "pre": ["geo_g011", "geo_g012"], "next": [], "content": {"advance": {"a": "主张说对了一半：排放是内因、是治理的根本抓手，这一点成立。但成因链是排放与气象相乘：同样的排放，遇上逆温静风就会酿成重污染天气。气象因素虽不能人为改变，却可以用来「管理时机」——利用天气预报做重污染预警、提前启动应急减排、错峰生产与限行，把扩散最差时段的排放压下来。完整的治理观是：常态减排降总量，气象预警管峰值。", "kind": "self", "q": "有人主张「治理雾霾只要工厂和汽车减排就行，天气因素管不了也不用管」。用成因链评价这一主张，并说明气象条件在治理中能发挥什么实际作用。"}, "apply": [{"ans": 1, "opts": ["逆温、静风", "冷空气南下、大风天气", "夜间晴朗、辐射冷却强", "盆地地形、无风"], "q": "下列气象条件中，最有利于污染物扩散的是（ ）", "why": "大风加快水平扩散、冷空气活动破坏逆温层，扩散条件最好；其余选项都是扩散不利条件。"}, {"ans": 1, "opts": ["汽车限行", "集中供暖与清洁能源替代散煤", "工地扬尘管控", "增加道路洒水频次"], "q": "某地冬季取暖燃煤是雾霾的重要来源，与之最对应的治理措施是（ ）", "why": "对策与成因一一对应：燃煤源对应能源结构与供暖方式改造，限行对应的是交通源。"}], "basics": [{"ans": 1, "opts": ["气温随高度升高而降低", "气温随高度升高而增加", "气压随高度升高而增加", "风速随高度升高而减小"], "q": "逆温是指对流层中出现的（ ）现象", "why": "逆温是气温随高度增加而升高的反常层结，它会抑制大气对流。"}, {"ans": 0, "opts": ["推广新能源汽车、发展公共交通", "集中供暖替代散煤", "施工工地洒水降尘", "植树造林增加绿地"], "q": "下列措施中，直接针对交通污染源的是（ ）", "why": "新能源汽车与公共交通对应汽车尾气这一交通源；其余分别对应燃煤、扬尘与生态吸附。"}], "case": {"a": "0—200 m 出现逆温，抑制垂直扩散，叠加静风使水平扩散缓慢，污染物在近地面累积，故清晨最重；日出后逆温破坏、对流恢复，污染随之减轻。", "hints": ["正常对流层气温随高度递减（约 0.6 ℃/100 m），这里却是随高度升高——方向反了。", "扩散有垂直和水平两个方向，材料里两个方向各给了一个不利条件。"], "q": "某城市冬日清晨探空数据：近地面（0 m）气温 −2 ℃，100 m 处 0 ℃，200 m 处 1 ℃，当日近地面风速不足 1 m/s；当天上午 10 时后逆温层被破坏，空气质量明显好转。①0—200 m 的气温变化说明出现了什么现象？它怎样影响污染物扩散？②为什么同一天上午 10 时后空气质量会好转？③该市工业与燃煤排放并未在当天突变，为什么清晨污染最重？", "steps": ["0—200 m 气温随高度升高由 −2 ℃升至 1 ℃，与正常递减相反，出现逆温现象（逆温层）。", "逆温层像盖子一样抑制空气对流，污染物无法向上扩散稀释；同时风速不足 1 m/s，水平扩散也很慢，污染物在近地面累积。", "上午 10 时后太阳辐射增强、地面增温，逆温层被破坏，对流恢复，污染物得以向上扩散，空气质量好转。", "结论：排放量当天基本不变，污染轻重之差主要由扩散条件（逆温有无、风速大小）决定——成因分析必须排放与气象两段齐全。"], "talk": ["污染成因题用「×」不用「+」：排放再多、扩散好也不积；排放不变、逆温加静风照样爆表。答题时两段成因都要落笔。"], "title": "案例：读逆温数据，断清晨雾霾为何最重"}, "intro": "蓝天不是理所当然的：它取决于污染物排多少、天气帮不帮着扩散。==问题研究的方法只有一条：把**成因链**拆开——污染源排放是内因，**逆温**、静风等气象条件是外因，然后让每一条**防治措施**都对准链条上的一环。==这一课考的不是背口号，是「对症下药」的对应关系。", "learn": [{"h": "雾霾成因链：排放 × 气象，两头都要占齐", "p": "**污染物排放**是内因：工业废气、汽车尾气、燃煤取暖、建筑扬尘、秸秆焚烧等排放大量颗粒物（PM2.5、PM10）与气态污染物。**气象条件**是外因：出现**逆温**（对流层中气温随高度升高而增加）时，大气层结稳定，空气对流受抑制，污染物难以向上扩散；**静风**（风速小）时水平扩散也慢；再加上低气压、地形封闭（盆地、河谷）等因素，污染物在近地面越积越多。\n\n==答成因题的固定结构：先排放（有什么源），后气象（为什么散不掉），两段缺一不可。=="}, {"h": "防治措施：一条对策对一环成因", "p": "对**能源**：调整能源结构，推广清洁能源，集中供暖替代散煤燃烧。对**产业**：淘汰落后产能、工业废气达标排放与深度治理。对**交通**：提升燃油品质、推广新能源汽车、发展公共交通、合理限行。对**扬尘与面源**：施工工地防尘、道路洒水、秸秆禁烧与综合利用。对**生态**：植树造林、增加绿地，吸附滞尘。对**管理**：加强监测预警、区域联防联控、重污染天气应急响应。\n\n==对策题的阅卷逻辑是「对应」：写措施时心里要能说出它堵的是哪一个排放源或改善哪一个扩散条件。=="}, {"h": "易错提醒：逆温是帮凶，不是污染源", "p": "易错提醒：逆温本身不产生污染物，它只是让污染物「散不掉」；晴朗的冬夜地面辐射冷却强，最容易形成**辐射逆温**，所以冬季清晨常是雾霾最重的时段。分析蓝天何时常在，既要算减排的账，也要看扩散条件的账。"}], "pitfalls": ["成因只答排放、漏掉逆温与静风等扩散条件（丢一半分）。", "把逆温当成污染源（它只影响扩散，不产生污染物）。", "对策写成口号堆砌，与成因对不上环（阅卷按对应关系给分）。"], "svg": "<rect x='15' y='30' width='105' height='30' rx='6' fill='#fee2e2'/><text x='67' y='50' text-anchor='middle' font-size='11'>排放：工业/交通</text><rect x='15' y='70' width='105' height='30' rx='6' fill='#fee2e2'/><text x='67' y='90' text-anchor='middle' font-size='11'>燃煤 · 扬尘</text><rect x='150' y='30' width='105' height='30' rx='6' fill='#e0f2fe'/><text x='202' y='50' text-anchor='middle' font-size='11'>逆温：对流受抑</text><rect x='150' y='70' width='105' height='30' rx='6' fill='#e0f2fe'/><text x='202' y='90' text-anchor='middle' font-size='11'>静风：水平扩散慢</text><rect x='285' y='50' width='90' height='34' rx='6' fill='#fef3c7'/><text x='330' y='71' text-anchor='middle' font-size='12'>雾霾加重</text><text x='195' y='125' text-anchor='middle' font-size='12'>成因 = 排放（内因） × 气象（外因） → 对策逐环对应</text>", "svgCap": "雾霾成因链：污染排放与不利扩散条件相乘，对策要逐环对应。"}, "video": {"bvid": "BV1eW4y1g79r", "p": 1, "t": "问题研究：何时蓝天常在", "dur": "18:38", "vtop": ["大气污染的范围和强度由污染源、气象条件、地表特点共同决定", "分析污染成因永远分两栏：自然因素和社会经济因素", "治理先认清主要污染源：洛杉矶治尾气、伦敦治燃煤，药要对症"], "vsum": "这一课围绕一个问题：蓝天怎样才能常在。背景是2013年重污染频发，国家出台**大气污染防治行动计划（大气十条）**、打响**蓝天保卫战**，空气明显改善，但重污染天数仍是难题。先认概念：**大气污染**指大气成分超标或有毒有害物质进入大气并造成危害，其范围和强度受污染源性质、**气象条件**和地表特点影响；空气质量用**空气质量指数（AQI）**分六级，盯的主要污染物有细颗粒物、可吸入颗粒物、二氧化硫、二氧化氮、臭氧、一氧化碳六项。==分析污染成因永远分两栏：自然因素（静稳天气多、盆地谷地地形不利于扩散）和社会经济因素（能源结构以煤为主、机动车尾气、城镇化扬尘、产业结构与监管）==，这套分法就是**区位因素**分析。对照国外：洛杉矶**光化学烟雾**源于汽车尾气，伦敦烟雾事件源于燃煤，污染源不同，治理路径和所需时间就不同。我国的措施可归为减排、控高耗能行业、推清洁能源、调产业结构、区域**联防联控**和全民参与。\n易错提醒：原因类题目先分自然与人为再下笔——冷空气减弱、冬季干旱是自然因素，以煤为主、汽车尾气是人为因素，混写最丢分；洛杉矶是尾气型、伦敦是燃煤型，也别张冠李戴。", "vtech": [["看到「分析某地大气污染的原因」", "先分两栏：自然因素（气象、地形）和社会经济因素（能源结构、产业、交通、人口、监管），逐栏点名不要漏"], ["看到「判断哪些是自然原因、哪些是人为原因」", "气候、地形、天气形势归自然，烧煤、开车、搞建设归人为"], ["看到「比较两个污染事件」", "先比污染源（尾气型还是燃煤型），再比治理难度和时间"], ["看到「提出治理措施」", "对着成因反着写：能源结构有问题就调结构、推清洁能源，地形扩散不利就写区域联防联控，监管不到位就写立法与执法"]], "vgaokao": [], "from": "会打快板的地理老师"}}}, "units": {"u_geo_1": {"id": "u_geo_1", "name": "地球的宇宙环境", "secs": "第一节", "pageFrom": 2, "pageTo": 7, "members": ["geo_g001", "geo_g002"], "video": {"bvid": "BV1VCxQedEVW", "p": 4, "t": "1-1【辞典】地球的宇宙环境", "dur": "38:34", "from": "一地er", "vtop": ["天体判断两条：位置在宇宙空间、本身是物质实体。", "层次顺序：地月系→太阳系→银河系→可观测宇宙。", "生命条件五条：光稳、道安、温度、大气、液态水。"], "vsum": "第一节解决定位问题：天体（恒星、行星、卫星、星云、彗星、流星体）与现象（流星、极光）要分清；**天体系统**四层次（地月系、太阳系、银河系、可观测宇宙）要背序；八大行星水金地火、木土、天海，**小行星带**在火星与木星之间。地球的特殊性用五条条件框架表达——外部：太阳光照稳定、行星各行其道；自身：**日地距离适中**（温度适宜）、体积质量适中（大气适宜）、有液态水。==这五条是本章所有大题的答题目录==。视频为一地er《高中地理必修一基础与考点大合集》1-1【辞典】地球的宇宙环境（38:34）。\n易错提醒：流星、极光是自然现象而不是天体，判断天体时千万别把它们算进去。", "vtech": ["看到「是不是天体」→ 只问两句：在宇宙空间吗？是实物吗？", "看到宜居性分析题 → 拿出五条清单逐条对：有/无+证据，不许凭感觉。", "看到行星排序/分类 → 先写口诀（水金地火木土天海）再落笔选项。"], "vgaokao": []}}, "u_geo_2": {"id": "u_geo_2", "name": "太阳对地球的影响", "secs": "第二节", "pageFrom": 8, "pageTo": 13, "members": ["geo_g003", "geo_g004"], "video": {"bvid": "BV1VCxQedEVW", "p": 6, "t": "1-2【辞典】太阳对地球的影响", "dur": "29:04", "from": "一地er", "vtop": ["辐射强弱看三样：纬度、海拔、天气（云量）。", "黑子是标志（光球层），耀斑是显示（色球层）。", "太阳活动影响：通信、磁暴、极光、气候。"], "vsum": "第二节分辐射与活动两半：太阳辐射源于**核聚变**，提供光热、驱动大气与水循环、是化石燃料的能量源头；==分布由低纬向高纬递减==，我国极值是青藏高原（海拔高、空气稀薄）与四川盆地（云雾多），且辐射强不等于气温高。太阳活动按层次记：光球层**黑子**（11 年周期、活动标志）、色球层**耀斑**（最激烈显示）、日冕层**太阳风**；影响四条：扰动电离层影响短波通信、磁暴、极光（高纬）、与气候相关。视频为一地er《高中地理必修一基础与考点大合集》1-2【辞典】太阳对地球的影响（29:04）。\n易错提醒：黑子是太阳活动的标志、耀斑是太阳活动最激烈的显示，两者的说法不能互换。", "vtech": ["看到辐射强弱比较 → 三要素 checklist：纬度、海拔、云量，逐项比完再下结论。", "看到黑子/耀斑概念题 → 先定位层次，标志与显示绝不互换。", "看到统计相关材料 → 措辞只用「相关/可能影响」，不写「决定」。"], "vgaokao": []}}, "u_geo_3": {"id": "u_geo_3", "name": "地球的历史", "secs": "第三节", "pageFrom": 14, "pageTo": 20, "members": ["geo_g005", "geo_g006"], "video": {"bvid": "BV1VCxQedEVW", "p": 8, "t": "1-3【辞典】地球的历史", "dur": "36:15", "from": "一地er", "vtop": ["地层下老上新，化石是时间标签兼环境说明书。", "四幕剧：蓝藻放氧→生物登陆→恐龙称霸→人类出现。", "两次大灭绝（古生代末、中生代末）是时代分界。"], "vsum": "第三节是时间之书：沉积地层下老上新，==化石既断代又能推环境==（珊瑚→温暖浅海、三叶虫→古生代海洋）；**地质年代表**把 46 亿年分成**前寒武纪**（占约九成，蓝藻放氧改大气）与**显生宙**三代——古生代（海洋繁盛→生物登陆、蕨类成煤）、中生代（爬行动物与恐龙、裸子植物、联合古陆解体）、新生代（哺乳动物、被子植物、人类与冰期）。两次大灭绝卡住代与代的边界。视频为一地er《高中地理必修一基础与考点大合集》1-3【辞典】地球的历史（36:15）。\n易错提醒：前寒武纪占了地球历史的约九成，千万别把它当成一段很短的早期阶段。", "vtech": ["看到化石题 → 走推理链：生物→环境→时代，一步一个得分点。", "看到演化排序 → 用四幕剧主角定位：蓝藻、三叶虫、恐龙、人类各归其幕。", "看到地层剖面图 → 先查有无倒转/断层，再用下老上新。"], "vgaokao": []}}, "u_geo_4": {"id": "u_geo_4", "name": "地球的圈层结构", "secs": "第四节", "pageFrom": 21, "pageTo": 27, "members": ["geo_g007", "geo_g008"], "video": {"bvid": "BV1VCxQedEVW", "p": 9, "t": "1-4【辞典】地球的圈层结构", "dur": "27:57", "from": "一地er", "vtop": ["横波只能过固体：消失处之下是液态外核。", "岩石圈 = 地壳 + 上地幔顶部，不等于地壳。", "生物圈渗透于气、水、岩三圈，没有独立一层。"], "vsum": "第四节内外两分：内部靠**地震波**——==纵波快且穿三态、横波慢且只穿固体==；**莫霍面**（壳幔界）与**古登堡面**（幔核界，约 2900 千米、横波消失→外核液态）分出地壳、地幔、地核，软流层是岩浆发源地，**岩石圈**=地壳+上地幔顶部。外部四圈：大气圈、水圈（连续不规则）、岩石圈、生物圈（渗透于其余三圈），相互联系构成人类生存环境。视频为一地er《高中地理必修一基础与考点大合集》1-4【辞典】地球的圈层结构（27:57）。\n易错提醒：岩石圈不等于地壳，它还包括上地幔的顶部，两个概念答题时不能混用。", "vtech": ["看到波速图 → 找突变点定界面，找横波消失定液态。", "看到圈层归属题 → 逐词扫描归类，再找一对作用关系最直接的。", "看到岩石圈 → 立刻默念：地壳+上地幔顶部，不是地壳本身。"], "vgaokao": []}}, "u_geo_5": {"id": "u_geo_5", "name": "问题研究：火星基地应该是什么样子", "secs": "问题研究", "pageFrom": null, "pageTo": null, "members": ["geo_g009"], "video": {"bvid": "BV1uG4y1R7eR", "p": 1, "t": "问题研究：火星基地应该是什么样子", "dur": "9:26", "vtop": ["研究一个地方能不能住人：先摸清自然情况，再对生命保障条件", "火星像地球在距日、自转和轴倾角，不像在缺氧、严寒和沙尘暴", "基地靠生态生保系统循环再生氧气、水和食物，再按功能分区"], "vsum": "这节是问题研究，套路先摆明：收集资料摸清火星表面自然情况，再分析基地的**基本生命保障条件**，参考人类**受控生态生保系统**的研究成就，最后按功能设计并画构想图。火星表面：大气稀薄、**二氧化碳占95%以上**、温差极大（赤道夏季白天21℃、夜间零下73℃）、多沙尘暴；但也发现了干涸河床、两极干冰冰盖和地下**水冰**。==火星与地球相近的是距日距离、自转周期和自转轴倾角，又有大气层和不同形态的水，这是它成为移民首选的底气==；短板是缺氧、平均零下52℃严寒、没有液态水、辐射强、没有食物来源。我国**绿航星际**实验用植物舱、乘员舱、生保舱、资源舱协作，在封闭舱内实现氧气、水和部分食物的**循环再生**，正是基地的样板。最后按登陆区、居住区、科研区、能源区分区，从形态、功能、防护三方面出方案。\n易错提醒：别把「有大气层」答成「有氧气」——火星大气几乎全是二氧化碳，不能直接呼吸；它的水以冰的形式存在，也不是现成的液态水。", "vtech": [["看到「某星球适不适合建基地、住人」", "先按自然情况清单逐项对：大气成分、温度、水、辐射、能源，有利和不利分开列"], ["看到「需要改造哪些条件」", "对着短板反着写：缺氧就制氧造大气、严寒就保温、水是冰就取冰化水"], ["看到「参考某实验的借鉴意义」", "抓它实现了什么的循环再生（氧气、水、食物），对应到基地的生命保障系统"], ["看到「设计功能分区」", "每个区写清形态、功能、防护三件事，再用通道连成整体"]], "vgaokao": [], "from": "会打快板的地理老师"}}, "u_geo_6": {"id": "u_geo_6", "name": "大气的组成和垂直分层", "secs": "第一节", "pageFrom": 28, "pageTo": 33, "members": ["geo_g010", "geo_g011"], "video": {"bvid": "BV1VCxQedEVW", "p": 10, "t": "2-1【辞典】大气的组成和垂直分层", "dur": "53:02", "from": "一地er", "vtop": ["干洁空气：氮 78%、氧 21%，CO₂ 与臭氧量少作用大。", "分层依据是温度垂直变化：对流层、平流层、高层大气。", "对流层约 12 km（低纬 17—18、高纬 8—9），递减率约 0.6 ℃/100 m。"], "vsum": "第一节先认成分再分层：**干洁空气**中氮气约 78%（生物体基本成分）、氧气约 21%（维持生命活动），二氧化碳是光合作用原料并吸收地面长波辐射保温，臭氧吸收紫外线护生；水汽是天气现象的原料，杂质是**凝结核**。人类活动两笔账：化石燃料使 CO₂ 增多导致全球变暖，氟氯碳化物破坏臭氧形成空洞。==垂直分层依据温度垂直变化：对流层平均约 12 千米==（低纬 17—18、高纬 8—9），气温以约 0.6 ℃/100 m 递减、天气现象尽在其中；**平流层**（顶约 50—55 千米）因臭氧吸收紫外线而上热下冷、气流平稳，宜于飞行；高层大气的电离层能反射无线电短波。视频为一地er《高中地理必修一基础与考点大合集》2-1【辞典】大气的组成和垂直分层（53:02）。\n易错提醒：二氧化碳增多对应的是全球变暖，臭氧空洞是氟氯碳化物造成的，两件事不能混为一谈。", "vtech": ["看到成分作用题 → 先分含量派（氮、氧）与关键派（CO₂ 保温、臭氧吸紫外线），再落笔。", "看到气温曲线判层 → 先看增减方向，再用 0.6 ℃/100 m 验算变化率，最后对层名与成因。", "看到飞行/通信题 → 飞行找平流层（平稳少水汽），短波通信找电离层。"], "vgaokao": []}}, "u_geo_7": {"id": "u_geo_7", "name": "大气受热过程和大气运动", "secs": "第二节", "pageFrom": 34, "pageTo": 45, "members": ["geo_g012", "geo_g013", "geo_g014"], "video": {"bvid": "BV1VCxQedEVW", "p": 12, "t": "2-2【辞典】大气的受热过程", "dur": "79:04", "from": "一地er", "vtop": ["受热三段：太阳暖大地、大地暖大气、大气还大地（逆辐射）。", "热力环流：热升低压、冷沉高压，高空与近地面气压相反。", "风的判读：先垂（梯度力）后偏（北右南左），高空平行、近地斜穿。"], "vsum": "第二节是一条能量—运动链：受热过程三段（太阳暖大地—削弱作用之后的短波到达地面；大地暖大气—==地面长波辐射是对流层大气的直接热源==；大气还大地—**大气逆辐射**起保温作用），用它解释阴天温差小、晴夜易霜冻、温室大棚保温。**热力环流**由冷热不均发动：热处上升成近地面低压、冷处下沉成近地面高压，高空相反，风由高压吹向低压；海陆风昼夜倒向、山谷风昼夜倒坡、城市风由郊吹城，都是同一环流。风的形成看三力：**水平气压梯度力**是原动力（等压线越密风越大），**地转偏向力**北右南左只改方向，摩擦力减速并使风向斜穿等压线；高空风平行等压线，近地面风斜交，风压定律可验算方向。视频为一地er《高中地理必修一基础与考点大合集》2-2【辞典】大气的受热过程（79:04）；热力环流与风的辞典在同合集紧接着的两集里。\n易错提醒：对流层大气的直接热源是地面辐射而不是太阳辐射，这是本节最容易答错的一点。", "vtech": ["看到昼夜温差题 → 双段答：白天削弱、夜间逆辐射保温，缺一段丢一半。", "看到局地风判向 → 先比冷热定升沉，再定近地面气压，最后风从高压吹向低压。", "看到等压线图 → 先看疏密定风速，再画梯度力（垂、向低），最后按半球偏转并用风压定律验算。"], "vgaokao": []}}, "u_geo_8": {"id": "u_geo_8", "name": "问题研究：何时蓝天常在", "secs": "问题研究", "pageFrom": null, "pageTo": null, "members": ["geo_g015"], "video": {"bvid": "BV1eW4y1g79r", "p": 1, "t": "问题研究：何时蓝天常在", "dur": "18:38", "vtop": ["大气污染的范围和强度由污染源、气象条件、地表特点共同决定", "分析污染成因永远分两栏：自然因素和社会经济因素", "治理先认清主要污染源：洛杉矶治尾气、伦敦治燃煤，药要对症"], "vsum": "这一课围绕一个问题：蓝天怎样才能常在。背景是2013年重污染频发，国家出台**大气污染防治行动计划（大气十条）**、打响**蓝天保卫战**，空气明显改善，但重污染天数仍是难题。先认概念：**大气污染**指大气成分超标或有毒有害物质进入大气并造成危害，其范围和强度受污染源性质、**气象条件**和地表特点影响；空气质量用**空气质量指数（AQI）**分六级，盯的主要污染物有细颗粒物、可吸入颗粒物、二氧化硫、二氧化氮、臭氧、一氧化碳六项。==分析污染成因永远分两栏：自然因素（静稳天气多、盆地谷地地形不利于扩散）和社会经济因素（能源结构以煤为主、机动车尾气、城镇化扬尘、产业结构与监管）==，这套分法就是**区位因素**分析。对照国外：洛杉矶**光化学烟雾**源于汽车尾气，伦敦烟雾事件源于燃煤，污染源不同，治理路径和所需时间就不同。我国的措施可归为减排、控高耗能行业、推清洁能源、调产业结构、区域**联防联控**和全民参与。\n易错提醒：原因类题目先分自然与人为再下笔——冷空气减弱、冬季干旱是自然因素，以煤为主、汽车尾气是人为因素，混写最丢分；洛杉矶是尾气型、伦敦是燃煤型，也别张冠李戴。", "vtech": [["看到「分析某地大气污染的原因」", "先分两栏：自然因素（气象、地形）和社会经济因素（能源结构、产业、交通、人口、监管），逐栏点名不要漏"], ["看到「判断哪些是自然原因、哪些是人为原因」", "气候、地形、天气形势归自然，烧煤、开车、搞建设归人为"], ["看到「比较两个污染事件」", "先比污染源（尾气型还是燃煤型），再比治理难度和时间"], ["看到「提出治理措施」", "对着成因反着写：能源结构有问题就调结构、推清洁能源，地形扩散不利就写区域联防联控，监管不到位就写立法与执法"]], "vgaokao": [], "from": "会打快板的地理老师"}}}, "nodeUnit": {"geo_g001": "u_geo_1", "geo_g002": "u_geo_1", "geo_g003": "u_geo_2", "geo_g004": "u_geo_2", "geo_g005": "u_geo_3", "geo_g006": "u_geo_3", "geo_g007": "u_geo_4", "geo_g008": "u_geo_4", "geo_g009": "u_geo_5", "geo_g010": "u_geo_6", "geo_g011": "u_geo_6", "geo_g012": "u_geo_7", "geo_g013": "u_geo_7", "geo_g014": "u_geo_7", "geo_g015": "u_geo_8"}};

